SELECT 'moj-all-verified-judgments-review-002-chunk-057' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e8bae93b-82a8-5ac7-8f69-8372b93994a0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -إقرار حتقيق ا -قبول الرجوع عن اإلقرار يف احلدود -تعزير للشبهة - احلدود تدرأ بالشبهات -التعزير باجللد .","document_number":"34263206","case_number":"34292127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -إقرار حتقيق ا -قبول الرجوع عن اإلقرار يف احلدود -تعزير للشبهة - احلدود تدرأ بالشبهات -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك‪ 34263206:‬تاريخه‪1434/7/9:‬هـ‬\n                        ‫رقم الدعوى‪34292127:‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34284484:‬تاريخه‪1434/8/01:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬إقــرار‬\n      ‫حتقيق ـ ًا ‪ -‬قبــول الرجــوع عــن اإلقــرار يف احلــدود ‪ -‬تعزيــر للشــبهة ‪-‬‬\n                               ‫احلــدود تــدرأ بالشــبهات ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n      ‫رجــوع املقــر عــن إقــراره مقبــول عنــد عامــة الفقهــاء قــال صاحــب الشــرح‬\n      ‫( ومتــى رجــع املقــر باحلــد عــن إقــراره قبــل منــه وإن رجــع يف أثنــاء احلــد‬\n      ‫لــم يتمــم وجملــة ذلــك أن شــرط إقامــة احلــد باإلقــرار البقــاء عليــه‬\n          ‫إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف عنــه ) قــال يف اإلنصــاف‬\n                                  ‫(هذا املذهب يف جميع احلدود)‪. 207-206/26‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وقيادة الســيارة‬\n      ‫حتــت تأثيــر املســكر ‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بحــد املســكر وإفهامــه بــأن عقوبتــه لقــاء قيــادة الســيارة حتــت تأثيــر‬\n      ‫املســكر عائــدة للجهــة املختصــة ‪،‬وحيــث جــرى اســتيقاف املدعــى عليــه‬\n      ‫مــن قبــل الدوريــة األمنيــة وتبــن أنــه بحالــة غيــر طبيعيــة ‪،‬وباستشــمامه‬\n      ‫اتضــح انبعــاث رائحــة مــن أنفاســه تشــبه رائحــة املســكر ‪،‬وقــد أنكــر‬\n      ‫املدعــى عليــه الدعــوى ‪،‬وكانــت بينــة املدعــي العــام إقــرار املدعــى‬\n\n‫‪245‬‬\n\f‫عليــه حتقيقـ ًا بشــرب املســكر ومحضــر االستشــمام ‪،‬ولرجــوع املدعــى‬\n‫عليــه عــن إقــراره ‪،‬ومبــا أن شــهادة الشــهود ليــس فيهــا جــزم بانبعــاث‬\n‫املســكر ‪،‬وإقامــة حــد املســكر علــى الرائحــة مختلــف فيــه عنــد أهــل‬\n‫‪،‬ولتوجــه التهمــة القويــة عليــه‬\n                            ‫ّ‬      ‫العلــم ‪،‬ومبــا أن احلــدود تــدرأ بالشــبهات‬\n‫حكمــت احملكمــة بتعزيــره بجلــده تســع ًا وســبعني جلــدة دفعــة واحــدة‬\n‫‪،‬وقنــع املدعــى عليــه باحلكــم ‪،‬واعتــرض املدعــي العــام بــدون الئحــة‬\n                              ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬  ‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34292127‬وتاريــخ ‪1434/06/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341534966‬وتاريــخ ‪ 1434/06/25‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/07/08‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام وقــدم الئحــة دعــواه ضد ‪.....‬ســعودي اجلنســية‬\n‫ا ‪ :‬إنــه بتاريــخ ‪1434/6/8‬ه ـ‬  ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائ ـ ً‬\n‫يف متــام الســاعة (‪ )10.27‬مــن مســاء يــوم اخلميــس أثنــاء اســتالم دوريــة‬\n‫األمــن بســوق ‪.....‬حضــر إليهــم املتهــم مدعيـ ًا علــى أشــخاص مــن اجلنســية‬\n‫اليمنيــة وباســتيقافه تبــن أنــه بحالــة غيــر طبيعيــة وباستشــمامه اتضــح‬\n‫انبعــاث رائحــة مــن أنفاســه تشــبه رائحــة املســكر وباســتجواب املتهــم‬\n‫أقــر بشــرب املســكر ‪ ،‬وقــد أثبــت تقريــر فحــص عينــة دم املتهــم‬\n‫الصــادر مــن جلنــة حتــري الكحــول باملستشــفى برقــم (‪ ).....‬وتاريــخ‬\n‫‪1434/6/14‬ه ـ إيجابيــة العينــة ملــادة الكحــول ‪ ،‬وقــد انتهــى التحقيــق‬\n                                                                                   ‫‪246‬‬\n\f      ‫إلــى اتهــام‪..... /‬بشــرب املســكر وقيــادة الســيارة حتــت تأثير املســكر‪،‬‬\n      ‫وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا لــذا اطلــب إثبــات إدانتــه مبــا أســند‬\n      ‫إليــه واحلكــم عليــه بحــد شــرب املســكر واثبــات إدانتــه بقيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر وإفهامــه بــان عقابــه عائــد للجهــة املختصــة وفقــا‬\n      ‫للمــادة (‪ )1/1/74‬مــن نظــام املــرور والئحتــه التنفيذيــة‪ .‬ويف نفــس‬\n      ‫اجللســة حضــر املدعــى عليــه فجــرى ســؤاله عمــا جــاء يف الئحــة املدعــي‬\n      ‫ا ‪ :‬كل مــا جــاء يف الئحــة املدعــي العــام مــن شــربي‬       ‫العــام فأجــاب قائـ ً‬\n      ‫للمســكر وقيادتــي الســيارة حتــت تأثيــره غيــر صحيــح هكــذا أجــاب‪،‬‬\n      ‫ا ‪ :‬بينتــي مــا جــاء بإقــرار‬‫ثــم ســألت املدعــي العــام عــن بينتــه فأجــاب قائـ ً‬\n      ‫املدعــى عليــه حتقيقـ ًا واملــدون علــى لفــة (‪ )10‬صفحــة (‪ )3‬وهــذا نصــه ‪:‬‬\n      ‫(أقــر أنــا ‪.....‬أنــي قمــت بتنــاول املســكر) ‪ ،‬ومــا جــاء يف محضــر القبــض‬\n      ‫واالستشــمام لفــة (‪ )2‬واملتضمــن ‪( :‬واتضــح انبعــاث رائحــة كريهــة منــه‬\n      ‫تشــبه رائحــة املســكر) ‪ ،‬ومــا جــاء بتقريــر جلنــة حتــري الكحــول لفــة‬\n      ‫(‪ )11‬واملتضمــن إيجابيــة عينــة دم املدعــى عليــه للكحــول ‪ ،‬وبعــرض‬\n      ‫ا ‪ :‬ال صحــة ملــا جــاء يف كالم‬        ‫ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫املدعــي العــام ‪ ،‬أمــا اإلقــرار فصحيــح أنــه صــدر منــي ولكنــه حتــت‬\n      ‫وطــأة التهديــد واإلكــراه هكــذا أجــاب ‪ ،‬فســألت املدعــي العــام هــل‬\n      ‫ا ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‬    ‫لديــك زيــادة بينــة فأجــاب قائـ ً‬\n      ‫ا ‪ :‬ال ســوابق علـ ّـي‬  ‫‪ ،‬وســألت املدعــى عليــه عــن ســوابقه فأجــاب قائ ـ ً‬\n      ‫وهلل احلمــد فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وإلنــكار‬\n      ‫ا ‪ ،‬ولرجوعــه عــن إقــراره‬       ‫املدعــى عليــه مــا نســب إليــه جملــة وتفصي ـ ً‬\n      ‫املثبــت حتقيق ـ ًا واملذكــور أعــاه والرجــوع عــن اإلقــرار يف احلــدود‬\n\n\n‫‪247‬‬\n\f‫مقبــول عنــد عامــة الفقهــاء قــال صاحــب الشــرح ( ومتــى رجــع املقــر‬\n‫باحلــد عــن إقــراره قبــل منــه وإن رجــع يف أثنــاء احلــد لــم يتمــم وجملــة‬\n‫ذلــك أن شــرط إقامــة احلــد باإلقــرار البقــاء عليــه إلــى متــام احلــد فــإن‬\n‫رجــع عــن إقــراره كــف عنــه ) قــال صاحــب اإلنصــاف ( هــذا املذهــب‬\n‫يف جميــع احلــدود ) ‪ ، 2080207/26‬وملــا جــاء بتقريــر جلنــة حتــري‬\n‫الكحــول املذكــور أعــاه ‪ ،‬ولكــون شــهادة الشــهود املدونــة بعاليــه‬\n‫ـاء‬\n ‫ليــس فيهــا اجلــزم بانبعــاث رائحــة املســكر و إقامــة حــد املســكر بنـ ً‬\n‫علــى الرائحــة عنــد اجلــزم بهــا مختلــف فيــه عنــد أهــل العلــم فعنــد عــدم‬\n‫اجلــزم مــن بــاب أولــى ‪ ،‬وألن احلــدود تــدرأ بالشــبهات ‪ ،‬ولعــدم وجــود‬\n‫ســوابق جنائيــة علــى املدعــى عليــه وجلميــع مــا تقــدم فلــم يثبــت لــدي‬\n‫إدانــة ‪.....‬بشــرب املســكر وقيادتــه الســيارة حتــت تأثيــره ورددت طلــب‬\n‫املدعــي العــام إقامــة حــد املســكر ‪ ،‬ولكــن لتوجــه التهمــة القويــة عليــه‬\n‫فقــد قــررت تعزيــره بجلــده تســعة وســبعني جلــدة دفعــة واحــدة وبذلــك‬\n‫حكمــت وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة باحلكــم وقــرر‬\n‫املدعــي العــام املعارضــة بــدون الئحــة وعليــه فقــد قــررت رفــع املعاملــة‬\n‫إلــى محكمــة االســتئناف كاملتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/08‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف باجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر بالنيابــة‬\n‫برقم‪341534966‬وتاريخ‪1434/7/11‬هـ ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشيخ‪...../‬املســجل برقــم ‪34263206‬يف‪1434/7/9‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضد‪...../‬التهامــه بشــرب املســكر وقــد‬\n\n\n                                                                                     ‫‪248‬‬\n\f      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬تقــرر املصادقــة علــى احلكــم‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪249‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":245,"source_page_end":249,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"49c45f3f5d4c5bf3377bcdc9dab009d140d454cc96521b31e7440fdde88a3165","normalized_text_hash":"b55cfbe6a69b5e340b11681c04ad9f0f362f962662328fb586510981f44adf70","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p245-34263206"},{"id":"5162cf01-a53c-5763-a713-4120caa91a8e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر وحيازته -قيادة سيارة حتت تأثير املسكر -حد املسكر -هروب من رجال األمن -التعزير بالسجن واجللد .","document_number":"34263461","case_number":"34308172","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"مسكر -شرب املسكر وحيازته -قيادة سيارة حتت تأثير املسكر -حد املسكر -هروب من رجال األمن -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34263461 :‬تاريخه‪1434/7/9:‬هـ‬\n                        ‫رقم الدعوى‪34308172 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34297697‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر وحيازتــه ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر‪ -‬حــد‬\n              ‫املســكر ‪ -‬هــروب مــن رجــال األمــن ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n      ‫‪ -2‬عــن ابــن عمــر رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال ( لعــن اهلل اخلمــر وشــاربها وســاقيها ومبتاعهــا وبائعهــا وعاصرهــا‬\n                   ‫ومعتصرهــا وحاملهــا واحملمولــة إليــه ) أخرجــه أبــوداود ‪.‬‬\n      ‫‪ -3‬عــن ابــن عبــاس رضــي اهلل عنهمــا قــال ســمعت رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم يقــول ( أتانــي جبريــل فقــال يــا محمــد إن اهلل لعــن اخلمــر‬\n      ‫وعاصرهــا ومعتصرهــا وشــاربها واحملمولــة إليــه وبائعهــا ومبتاعهــا‬\n      ‫وساقيها ومسقيها ) أخرجه أحمد وابن حبان يف صحيحه واحلاكم‪.‬‬\n      ‫‪ -4‬عــن ابــن عمــر رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫قــال ( ثالثــة حــرم اهلل تبــارك وتعالــى اجلنــة مدمــن اخلمــر والعــاق‬\n                                        ‫والديــوث الــذي يقــر يف أهلــه اخلبــث ) ‪.‬‬\n      ‫‪ -5‬عــن جابــر بــن عبــداهلل رضــي اهلل عنــه أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم قال ( كل مســكر خمر إن اهلل عهد ملن يشــرب املســكر أن يســقيه‬\n                       ‫اهلل مــن طينــة اخلبــال ‪ )..‬أخرجــه مســلم يف صحيحــه ‪.‬‬\n      ‫‪ -6‬ذكــر ابــن القيــم يف زاد املعــاد ‪ ( 42/5‬ويف مصنــف عبدالــرزاق أنــه‬\n‫‪263‬‬\n\f                      ‫صلــى اهلل عليــه وســلم جلــد يف اخلمــر ثمانــن ) ‪.‬‬\n‫‪ -7‬ذكــر املــرداوي يف اإلنصــاف ‪ ( 422 -421/26‬ومــن شــربه مختــار ًا‬\n‫ا كان أو كثيــر ًا فعليــه احلــد ثمانــون‬ ‫عامل ـ ًا أن كثيــره يســكر قلي ـ ً‬\n‫جلــدة وهــذا املذهــب ‪ ،‬وعليــه جماهيــر األصحــاب وجــزم بــه اخلرقــي‬\n                                                           ‫وابــن عقيــل ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بشــرب املســكر وحيازتــه‬\n‫ومحاولــة الهــروب مــن رجــال األمــن واتهــام األول بقيــادة الســيارة حتــت‬\n‫تأثيــر املســكر واالعتــداء علــى مركبــة رســمية ‪،‬وطلب إثبات ما أســند‬\n‫إليهمــا واحلكــم عليهمــا بحــد املســكر وتعزيرهمــا لقاء ما أســند إليهما‬\n‫وإثبــات إدانــة املدعــى عليــه األول لقــاء قيادتــه حتــت تأثيــر املســكر‬\n‫وتشــديد العقوبــة عليــه وفــق األنظمــة والتعليمــات ‪،‬حيــث كان املدعــى‬\n‫عليــه يقــود ســيارته بســرعة جنونيــة فقــام باالرتطــام بســيارة الدوريــة‬\n‫وارتكــب الفــرار ممــا أدى إلــى ارتطامــه بســيارة أخــرى فتــم ضبــط‬\n‫املدعــى عليهمــا بعــد محاولتهمــا الهــرب علــى أقدامهــم ومعهمــا شــخص‬\n‫آخــر فــرزت لــه أوراق مســتقلة كمــا وجــد قــارورة بهــا مــادة مســكره‬\n‫‪،‬وحضــر املدعــى عليــه األول ولــم يحضــر الثانــي ‪،‬وصــادق علــى الدعوى‬\n‫ماعــدا االعتــداء علــى املركبــة الرســمية واصطدامــه بهــا فأنكــر ذلــك‬\n‫وأنهــا هــي مــن ارتطمــت بــه مــن اخللــف ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بجلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر وصــرف‬\n‫النظــر عمــا طلبــه املدعــي العــام مــن تعزيــره علــى الكميــة التــي معــه‬\n‫وذلــك لقلتهــا ولعــدم توفــر موجبــه وإفهــام املدعــى عليــه بــأن عقوبتــه على‬\n                                                                                     ‫‪264‬‬\n\f      ‫قيــادة الســيارة حتــت تأثيــر املســكر لولــي األمــر وســجن املدعــى عليــه‬\n      ‫مــدة ســتة أشــهر الصطدامــه بســيارة الدوريــة ومحاولــة الهــرب وجلــده‬\n      ‫مائــة جلــدة مفرقــة علــى دفعتــن كل دفعــة خمســن ‪،‬وبالنســبة للمدعى‬\n      ‫عليــه الثانــي فتبقــى قضيتــه وتفــرز لــه أوراق مســتقلة ألن املدعــى عليــه‬\n      ‫األول ســجني ‪،‬وقنــع املدعــى عليــه ‪،‬واعتــرض املدعــي العــام مكتفي ـ ًا‬\n                ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬  ‫بالئحــة الدعــوى ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 34308172‬وتاريــخ ‪1434/07/04‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341613287‬وتاريــخ ‪1434/07/04‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافق‪1434/07/09‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n      ‫للنظــر يف الدعــوى املرفوعــة مــن املدعــي العــام ضــد ‪.....‬و‪.....‬بطلــب‬\n      ‫إثبــات الهــروب وإيقــاع حــد املســكر وفيهــا حضــر املدعــي العــام ‪.....‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪.....‬يحمــل ســجل مدنــي رقــم (‪).....‬موقــوف‬\n      ‫قائــا يف دعــواه بتاريــخ ‪1434/6/15‬ه ـ تســلم مركــز الشــرطة تقريــر‬\n      ‫إحــدى فــرق الدوريــات األمنيــة رقــم (‪ ).....‬املتضمــن أثنــاء قيــام الفرقــة‬\n      ‫بعملهــا علــى شــارع ‪.....‬اصطدمــت مبركبتهــم الرســمية ســيارة نــوع‬\n      ‫حتمــل اللوحــة رقــم (‪ ).....‬يقودهــا املدعــى عليــه ‪.....‬وكانــت تســير‬\n      ‫بســرعه جنونيــه فقــام باالرتطــام بســيارة الدوريــة وارتكــب الفــرار ممــا‬\n      ‫أدى إلــى ارتطامــه بســيارة أخــرى وضبــط املدعــى عليهمــا أعــاه بعــد‬\n      ‫محاولتهــم الهــرب علــى أقدامهــم ومعهمــا شــخص يدعــى ‪ (.....‬مت فــرز‬\n‫‪265‬‬\n\f‫أوراق مســتقله للقبــض عليــه) ووجــد قــارورة مــاء صحــة بهــا الربــع مــن‬\n‫مــادة مســكره‪ .‬وورد تقريــر املــرور املتضمــن أن نســبة اخلطــأ ‪ %100‬علــى‬\n‫املدعــى عليــه ‪...../‬ومت إعــداد محضــر باستشــمام املذكوريــن وتبــن‬\n‫انبعــاث رائحــة املســكر مــن فيهمــا‪ .‬وبســماع أقــوال رجــل األمــن‪...../‬‬\n‫أفــاد انــه أثنــاء قيامــه بعملــه ويرافقــه رجــل األمن‪...../‬علــى شــارع ‪.....‬‬\n‫ارتطمــت بهمــا الســيارة املوصوفــة أعــاه مــن جهــة الرفــرف األمامــي‬\n‫األميــن وارتكــب الفــرار وكان بالســيارة ثالثــة أشــخاص وهــم املدعــى‬\n‫عليهمــا املذكوريــن وكان يقــود الســيارة املتهــم‪..... /‬و معهــم شــخص‬\n‫يدعــى ‪.....‬وبســماع أقــوال رجــل األمــن‪ ........../‬أفــاد بانــه أثنــاء عملــه‬\n‫مرافــق للعســكري ‪ .....‬قامــت الســيارة املذكــور أوصافــه أعــاه‬\n‫باالرتطــام بســيارة الدوريــة األمنيــة ثــم ارتكــب الفــرار ومت القبــض علــى‬\n‫املدعــى عليهمــا املذكوريــن أعــاه ويقــود الســيارة املدعــى عليــه‪...../‬‬\n‫وباســتجواب املدعــى عليــه ‪...../‬اقــر بشــرب املســكر و بقيــادة الســيارة‬\n‫حتــت تأثيــر املســكر وباالرتطــام بســيارة دوريــة امنيــه والهــروب مــن‬\n‫الدوريــات األمنيــة وحيــازة املســكر وأضــاف أنــه كان هــارب مــن‬\n‫ســيارة دوريــة أمنيــة أخــرى غيــر التــي ارتطــم بهــا وأن ســيارة الدوريــة‬\n‫اعترضتــه وهــو يقــود ســيارته فارتطــم بهــا وأضــاف أن املدعــو ‪...../‬ال‬\n‫يعرفــه إمنــا ركــب معهمــا لغــرض توصيلــه وليــس لــه عالقــة بالقضيــة ‪.‬‬\n‫وباســتجواب املتهــم ‪...../‬أفــاد انــه كان راكــب مــع املدعــى عليــه‪...../‬‬\n‫وانهمــا كانــا يشــربان املســكر وقامــت دوريــة أمنيــة مبحاولــة إيفاقهمــا‬\n‫فهــرب املدعــى عليــه ‪.....‬بســيارته وارتطــم بدوريــة أمنيــة ملــا أشــير إليــه‬\n‫اقــرر اتهــام األول‪ .......... /‬و الثاني‪...../‬بشــرب املســكر وحيازتــه واتهــام‬\n‫األول ‪ .....‬بقيــادة الســيارة حتــت تأثيــره واالعتــداء علــى مركبــة رســمية‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫واتهــام األول والثانــي‪ /‬مبحاولــة الهــرب مــن رجــال األمــن ‪.‬وذلــك لألدلــة‬\n                                                                        ‫والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا ورد بأقــوال املدعــى عليهمــا املنــوه عنهــا واملدونــة علــى اللفــة رقــم‬\n                                                                                         ‫( )‪.‬‬\n                 ‫‪ -2‬ما ورد بتقرير الدوريات األمنية املنوه عنه واملدون لفه (‪.)5‬‬\n                       ‫‪ -3‬ما ورد يف تقرير املرور املنوه عنه واملرفق لفه رقم (‪.)3‬‬\n      ‫‪ -4‬مــا ورد يف محضــر االستشــمام املنــوه عنــه واملــدون علــى اللفــة رقــم‬\n      ‫(‪ .)1‬وحيــث إن مــا أقــدم عليــه املذكــوران فعــل معاقــب عليــه شــرعا لــذا‬\n      ‫اطلــب بعقوبــة حــد املســكر وتعزيرهمــا لقــاء مــا أســند إليهمــا وللمدعــى‬\n      ‫عليــه ‪.....‬النظــر فيمــا يتعلــق بقيادتــه للســيارة حتت تأثير شــرب املســكر‬\n      ‫املعاقــب علــى ذلــك مبوجــب الفقــرة الثانيــة مــن املــادة (‪ )68‬مــن املرســوم‬\n      ‫امللكي رقم (م‪ )85/‬وتاريخ ‪1428/10/26‬هـ وتشديد العقوبة استنادا‬\n      ‫لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )36717‬وتاريــخ ‪1431/6/11‬ه ـ‬\n      ‫‪،‬علمــا بانــه مت تســديد تلفيــات الدوريــة األمنيــة البالــغ قيمتهــا (‪)7000‬‬\n      ‫ريــال‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه عن دعــوى املدعي العام أجاب‬\n      ‫قائــا كلمــا ذكــره املدعــي العــام مــن قيامــي بقيــادة ســيارة مــن نــوع‬\n      ‫وهــي حتمــل اللوحــة التــي ذكرهــا فهــذا كلــه صحيــح وأمــا مــا ذكــره‬\n      ‫مــن أننــي ارتطمــت بالدوريــة فليــس بصحيــح والصحيــح بــأن ســيارة‬\n      ‫الدوريــة قــد طلبــت منــي التوقــف فلــم اســتجب فاصطدمت بــي من اخللف‬\n      ‫ممــا أدى إلــى صدمــي بالســيارة األماميــة وقــد شــربت املســكر وكان‬\n      ‫بحوزتــي ربــع قــارورة صغيــره بهــا مســكر ولــم أهــرب مــن املــكان وأنــا‬\n      ‫مخطــئ ونــادم وكنــت اقــود الســيارة وأنــا بحالــه ســكر هكــذا أجــاب‬\n      ‫هــذا كمــا جــرى االطــاع علــى لفــه رقــم (‪ )5‬وهــو تقريــر أولــي ونــص‬\n\n\n‫‪267‬‬\n\f‫احلاجــة منــه (حضــرت ســيارة مــن نــوع بســرعه جنونيــه ممــا أدى الــى‬\n‫ارتطامــه بســيارة الدوريــة فاصطــدم بالســيارة الواقفــة وارتكــب الفــرار‬\n‫أربعــة أشــخاص وضبــط ثالثــة ) اه ـ وبعــرض ذلــك علــى املدعــى عليــه‬\n‫قــال ال اعلــم حيــث أننــي كنــت يف وقتهــا ســكران هكــذا قــرر هــذا‬\n‫كمــا جــرى االطــاع علــى ملــف محاضــر لفــه رقــم(‪ )1‬وصحيفــه (‪)11‬‬\n‫ونــص احلاجــة منهــا (أنــا ‪..........‬وعنــد االصطــدام هــرب ‪.....‬وعــاد للموقــع‬\n‫)اه ـ وبعــرض ذلــك علــى املدعــى عليــه قــال ميكــن ذلــك هكــذا قــرر‬\n‫وباالطــاع علــى املعاملــة لــم أجــد فيهــا حتليــل باملــادة التــي يف القــارورة‬\n‫وبنــا علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــه املدعــى عليــه علــى‬\n‫شــرب املســكر وصــدم ســيارة دوريــات األمــن وكذلــك قيادتــه للســيارة‬\n‫حتــت تأثيــر املســكر وال عــذر ملــن اقــر ومــا تضمنــه التقريــر األولــي‬\n‫وكذلــك مــا تضمنــه احملضــر واملــدون انفــا وقــد قــال اهلل عــز وجــل‬\n‫«يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون» ‪ ،‬ويف احلديــث عــن ابــن عمر‬\n‫رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قــال‪« :‬لعــن اهلل اخلمــر‬\n‫وشــاربها وســاقيها ومبتاعهــا وبائعهــا وعاصرهــا ومعتصرهــا وحاملهــا‬\n‫واحملمولــة إليــه» أخرجــه أبــو داود‪ ،‬وعــن ابــن عبــاس رضــي اهلل عنهمــا‬\n‫قــال‪ :‬ســمعت رســول اهلل صلــى اهلل عليــه وســلم يقــول‪« :‬أتانــي جبريــل‬\n‫فقــال يــا محمــد إن اهلل لعــن اخلمــر وعاصرهــا ومعتصرهــا وشــاربها‬\n‫واحملمولــة إليــه وبائعهــا ومبتاعهــا وســاقيها ومســقاها» أخرجــه أحمــد‬\n‫بإســناد صحيــح‪ ،‬وابــن حبــان يف صحيحــه واحلاكــم‪ ،‬وعــن عبــداهلل بــن‬\n‫عمــر رضــي اهلل عنهمــا أن الرســول صلــى اهلل عليــه وســلم قــال‪« :‬ثالثــة‬\n‫حــرم اهلل تبــارك وتعالــى اجلنــة‪ :‬مدمــن اخلمــر‪ ،‬والعــاق‪ ،‬والديــوث الــذي‬\n\n\n                                                                                       ‫‪268‬‬\n\f      ‫يقــر يف أهلــه اخلبــث»‪ ،‬وقــد انعقــد اإلجمــاع علــى أن اخلمــر حــرام شــربه‬\n      ‫واســتعماله كيفمــا كان االســتعمال‪ ،‬وذلــك ممــا علــم مــن الديــن‬\n      ‫بالضــرورة‪ ،‬وعــن جابــر بــن عبــداهلل أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم قــال‪« :‬كل مســكر خمــر‪ ،‬إن اهلل عهــد ملــن يشــرب املســكر‬\n      ‫أن يســقيه مــن طينــة اخلبــال‪ ،‬قالــوا يــا رســول اهلل مــا طينــة اخلبــال؟ قــال‪:‬‬\n      ‫عــرق أهــل النــار» أخرجــه مســلم يف صحيحــه وقــد ذكــر ابــن القيــم‬\n      ‫رحمــه اهلل تعالــى يف كتابــه زاد املعــاد ‪ 42/5‬مــا نصــه‪« :‬ويف مصنــف‬\n      ‫عبدالــرزاق أنــه صلــى اهلل عليــه وســلم جلــد يف اخلمــر ثمانــن» أ‪.‬هــ‪ .‬وقــد‬\n      ‫ذكــر املــرداوي يف كتابــه اإلنصــاف ‪ 422-421/26‬مــا نصــه‪« :‬ومــن‬\n      ‫شــربه مختــارا عاملــا أن كثيــره يســكر قليــا كان أو كثيــرا فعليــه‬\n      ‫احلــد ثمانــون جلــدة وهــذا املذهــب وعليــه جماهيــر األصحــاب‪ ،‬وجــزم بــه‬\n      ‫اخلرقــي وابــن عقيــل» أ‪.‬هــ‪ .‬وكذلــك إقــراره بانــه ميكــن انــه قــد هــرب‬\n      ‫ألنــه يف حالــه ســكر وقــد قــرر العلمــاء رحمهــم اهلل تعالــى بــان التعزيــر‬\n      ‫يدخــل يف احلــد لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪..........‬بشــرب‬\n      ‫املســكر وحيازتــه بربــع قــارورة مــاء صحــه بداخلهــا وقيادتــه الســيارة‬\n      ‫حتــت تأثيــر املســكر واالعتــداء علــى مركبــه رســميه ومحاولــة الهــرب‬\n                                             ‫جلميــع ذلــك فقــد حكمــت باآلتــي أوال‪:‬‬\n             ‫بجلد املدعى عليه ‪.....‬ثمانني جلده دفعه واحده وهو حد املسكر‬\n      ‫ثانيــا‪ :‬صرفــت النظــر عمــا طلبــه املدعــي العــام مــن تعزيــره علــى الكميه‬\n                                  ‫التــي معــه وذلــك لقلتهــا ولعــدم توفــر ســبب موجبه‬\n      ‫ثالثــا ‪ :‬أفهمــت املدعــى عليــه ‪.....‬بــان عقابــه علــى قيادتــه الســيارة حتــت‬\n                                                            ‫تأثيــر املســكر لولــي األمــر‬\n      ‫رابعــا‪ :‬ســجن املدعــي عليــه ‪.....‬ملــده ســته اشــهر لقــاء اصطدامــه بســيارة‬\n\n\n‫‪269‬‬\n\f‫الدوريــة ومحاولــة الهــرب اعتبــارا مــن تاريــخ اإليقــاف ‪1434/06/15‬ه ـ‬\n‫وبجلــده مائــه جلــده علــى دفعتــن كل دفعــه خمســن جلــده بــن كل‬\n‫مــره واألخــرى ســبعه أيــام خامســا ‪ :‬أمــا بالنســبة للمدعــى عليــه الثانــي‬\n‫‪.....‬فتبقــى قضيتــه وتفــرز لــه أوراق مســتقله الن املدعــى عليــه األول‬\n‫ســجني وبعرضــه علــى املدعــى عليــه قــرر قناعتــه باحلكــم أمــا املدعــى‬\n‫العــام قــرر االعتــراض واكتفــى بالئحــة االدعــاء عــن الئحــة االعتــراض‬\n                                 ‫هكــذا قــرر حــرر بتاريــخ ‪1434/07/09‬ه ــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن رئيــس‬\n‫احملكمة اجلزائية بالرياض برقم ‪ 341613287‬وتاريخ ‪1434/7/16‬هـ‬\n‫واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة الشــيخ ‪.....‬‬\n‫برقــم ‪34263461‬وتاريــخ ‪1434/7/9‬ه ـ واخلــاص بدعــوى املدعــي العــام‬\n‫ضــد ‪ .....‬وموضوعهــا مســكر وانتهــاء الدراســة والتدقيــق باملصادقــة‬\n‫علــى احلكــم لعــدم موجــب املالحظــة ‪ ،‬مــع تنبيــه فضيلتــه إلــى التنويــه‬\n‫بحــق املدعــى عليه‪.....‬إلــى أنــه ســتجري محاكمتــه حــال إحضــاره واهلل‬\n                               ‫املوفــق ‪ .‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                                      ‫‪270‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":263,"source_page_end":270,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"56230debe261941278899a362da1f1bd0bd252e4c55223fa1ce32f4f778f3c72","normalized_text_hash":"7d72b7126cefe4dd5b439e2e121f9a11c5118806f441a6213fe17102cbe2db29","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p263-34263461"},{"id":"c34ab190-9ff0-5f5e-ab7d-df9c75c5d5f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -سرقة سيارة -إنكار السرقة -انطباق بصمات -تعزير للشبهة -التعزير بالسجن واجللد -إقامة حد املسكر .","document_number":"34271212","case_number":"34325002","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية الرابعة يف محكمة الاستئناف مبنطقة مكة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"مسكر -شرب املسكر -سرقة سيارة -إنكار السرقة -انطباق بصمات -تعزير للشبهة -التعزير بالسجن واجللد -إقامة حد املسكر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34271212:‬تاريخه‪1434/7/17:‬هـ‬\n                         ‫رقم الدعوى‪34325002:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34322777:‬تاريخه‪1434/09/20:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬ســرقة ســيارة ‪ -‬إنكار الســرقة ‪ -‬انطباق بصمات‬\n           ‫‪ -‬تعزير للشــبهة ‪ -‬التعزير بالســجن واجللد ‪ -‬إقامة حد املســكر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n                     ‫‪ -2‬وقوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n       ‫‪ -3‬وقوله صلى اهلل عليه وسلم ( كل مسكر خمر وكل خمر حرام )‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                                    ‫ومالــه وعرضــه ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وســرقة‬\n      ‫ســيارة‪،‬وطلب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر‬\n      ‫وتعزيــره لقــاء ســرقة الســيارة وتشــديد العقوبــة لتعــدد ســوابقه ‪،‬حيــث‬\n      ‫قبــض علــى املدعــى عليــه إثــر بــاغ أحــد األشــخاص املتضمــن بأنه أوقف‬\n      ‫ســيارته وهــي مفتوحــة األبــواب وعليــه املفتــاح وعنــد عودتــه لــم يجدهــا‬\n      ‫وأبلــغ عــن ســرقتها وبعدهــا بســاعات عثــر عليهــا وســلمت لــه وجــرى‬\n      ‫رفــع آثــار البصمــات مــن الســيارة ومبضاهاتهــا مــن قبــل األدلــة اجلنائيــة‬\n\n‫‪271‬‬\n\f‫انطبقــت علــى بصمــات املدعــى عليــه ومت القبــض عليــه ‪،‬وباستشــمامه‬\n‫اتضــح انبعــاث رائحــة املســكر مــن فيــه ‪،‬وصــادق املدعــى عليــه علــى‬\n‫الدعــوى مــا عــدا ســرقة الســيارة فأنكرهــا ‪،‬وكانــت بينــة املدعــي‬\n‫العــام خطــاب األدلــة اجلنائيــة املتضمــن تطابــق بصمــات املدعــى عليــه‬\n‫املوجــودة داخــل الســيارة علــى البصمــات املرفوعــة مــن الســيارة ‪،‬وبنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه بحــد املســكر‬\n‫بجلــده ثمانــن جلــدة دفعــة واحــدة علن ـ ًا أمــام مــأ مــن النــاس ‪،‬وعــدم‬\n‫ثبــوت إدانــة املدعــى عليــه بســرقة الســيارة إال أن الشــبهة تتجــه النطبــاق‬\n‫بصماتــه وتعــدد الســوابق ‪،‬وتعزيــره بالســجن مــدة شــهرين وجلــده ثالثني‬\n‫جلــدة مكــررة عليــه مرتــن ‪،‬وقنــع املدعــى عليــه واعتــرض املدعــي العام‬\n‫‪،‬وصــدق احلكــم‬‫لكنــه لــم يقــدم الالئحــة فســقط حقــه يف االعتــراض ُ‬\n                                                 ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34325002‬وتاريــخ‬\n‫‪ 1434/07/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341681212‬وتاريــخ‬\n‫‪ 1434/07/11‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/07/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 30‬لســماع دعــوى املدعــي العــام ضــد ‪ .....‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n‫‪ .....‬واملكلــف مــن قبــل هيئــة التحقيــق واالدعــاء العام مبباشــرة الدعاوى‬\n‫بهــذه احملكمــة مبوجــب كتابهــم رقــم ‪.....‬وتاريــخ ‪1433/03/06‬ه ـ‬\n\n                                                                                    ‫‪272‬‬\n\f      ‫نيابــة عــن املدعــى العــام ‪.....‬بفــرع هيئــة التحقيــق مبحافظــة جــدة‬\n      ‫وادعــى علــى ‪ 28 .....‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الهويــة رقــم‬\n      ‫(‪ ).....‬قائــا يف الئحتــه إنــه أنــه بتاريــخ ‪ 1434/6/6‬ه ـ قبــض عليــه‬\n      ‫بنــاء علــى البــاغ املقــدم بتاريــخ ‪ 1434/4/28‬ه ـ مــن املدعــي ‪ .....‬مينــي‬\n      ‫اجلنســية‪،‬املتضمن أنــه أوقــف ســيارته مــن نــوع كيــا رقــم لوحتهــا (‪).....‬‬\n      ‫وهــي مفتوحــة األبــواب وعليهــا املفتــاح وعنــد عودتــه لــم يجدهــا وأبلــغ‬\n      ‫عــن ســرقتها وبعدهــا بســاعات عثــر عليهــا وســلمت لــه ‪ ،‬وجــرى رفع آثار‬\n      ‫البصمــات مــن الســيارة ومبضاهاتهــا مــن قبــل األدلــة اجلنائيــة انطبقــت‬\n      ‫علــى بصمــات املدعــى عليــه وبإجــراء البحــث والتحريــات قبــض علــى‬\n      ‫املدعــى عليــه وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن فيــه‬\n      ‫وباســتجوابه اعتــرف بشــرب العــرق املســكر وقــد أســفر التحقيــق عــن‬\n      ‫توجيــه االتهــام إلــى املدعــى عليــه ‪ ..... /‬بشــرب املســكر وســرقة ســيارة‬\n                                          ‫املدعــي ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                                   ‫‪ -1‬ما جاء يف أقواله املدونة لفة (‪ )25‬ص( ‪)4-2‬‬\n      ‫‪ -2‬مــا جــاء يف محضــر الضبــط اجلنائــي املنــوه عنــه املرفــق بــاألوراق لفــه‬\n                                                                          ‫(‪ )23‬ص(‪)3-2‬‬\n      ‫‪ -4‬مــا جــاء يف خطــاب األدلــة اجلنائيــة بشــأن انطبــاق بصماتــه لفــة (‪)19‬‬\n      ‫‪ -5‬محضــر االستشــمام لفــة (‪ )23‬ص(‪ )4‬وبالبحــث عــن ســوابقه عثــر‬\n      ‫لــه علــى خمــس ســوابق مســجلة هــي‪1 :‬و‪ /2‬عقــوق والديــن ‪3 ،‬و‪/4‬شــرب‬\n      ‫املســكر ‪/5 ،‬شــرب املســكر وحيازتــه ‪ ،‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرع ًا اطلــب إثبــات مــا أسن ــد إليــه واحلكــم عليــه بحــد شــرب‬\n      ‫املســكر وتعزيــره لقــاء ســرقة ســيارة املدعــي وتشــديد العقوبــة عليــه‬\n\n\n‫‪273‬‬\n\f‫لتعــدد ســوابقه التــي لــم يرتــدع بعقوباتهــا علمــا بــأن احلــق اخلــاص انتهــى‬\n‫بالتنــازل هــذه دعــواي وبتــاوة الئحــة املدعــي العــام علــى املدعــى عليــه‬\n‫ا فقد‬  ‫ا كل مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيـ ً‬       ‫أجــاب قائـ ً‬\n‫قبــض علـ ّـي مــن قبــل الدوريــات األمنيــة بتاريــخ ‪1434/6 /6‬ه ـ لقيامــي‬\n‫بشــرب املســكر حتــى ســكرت وقــد أقدمــت علــى شــرب املســكر وأنــا‬\n‫ـرعا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى‬\n                                                   ‫مســلم وأعلــم أنــه محــرم شـ ً‬\n‫هــذا الفعــل أمــا مــا ذكــره املدعــي العــام مــن قيامــي بســرقة الســيارة‬\n‫فغيــر صحيــح هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه علــى أن‬\n‫ا بينتــي مــا جــاء يف‬‫املدعــى عليــه ‪ .....‬قــام بســرقة الســيارة أجــاب قائ ـ ً‬\n‫أوراق املعاملــة مــن أدلــه وقرائــن هكــذا أجــاب هــذا وقــد جــرى اطالعــي‬\n‫علــى أوراق املعاملــة وعلــى صحيفــة ســوابق املدعــى عليــه املرفقــة‬\n‫باملعاملــة باللفــة رقــم (‪ )16-15-14‬املتضمنــة وجــود عــدد خمــس ســوابق‬\n‫مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى أقــوال املدعــى‬\n‫عليــه املرفقــة باملعاملــة لفــة رقــم (‪ )25‬صحيفــة رقــم (‪ )4-3-2‬واملتضمــن‬\n‫إقــراره بشــرب املســكر وإنــكاره ســرقة الســيارة كمــا جــرى اطالعــي‬\n‫علــى محاضــر الضبــط اجلنائــي ومحضــر االستشــمام املرفــق باملعاملــة‬\n‫لفــه (‪ )23‬صحيفــة رقــم (‪ )4-3-2‬كمــا جــرى اطالعــي علــى خطــاب‬\n‫األدلــة اجلنائيــة بشــأن انطبــاق بصمــات املدعــى عليــه املوجــودة داخــل‬\n‫الســيارة علــى البصمــات املرفوعــة مــن الســيارة لفــة (‪ )19‬فوجــدت‬\n‫اجلميــع طبــق مــا ذكــره املدعــي العــام فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومــا قــرره الطرفــان وإلقــراره بشــرب املســكر ألنــه ال عــذر‬\n‫ملــن أقــر علــى نفســه وإنــكاره ســرقة الســيارة لــذا فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه املذكــور بعاليــه مبــا نســب إليــه يف الدعــوى مــن شــربه‬\n\n\n                                                                                       ‫‪274‬‬\n\f      ‫للمســكر كمــا لــم يثبــت لــدي إدانــة املدعــى عليــه مــن قيامــه بســرقة‬\n      ‫ســيارة املدعــي إال أن الشــبهة تتجــه نحــوه بفعــل ذلــك للقرائــن التاليــة‪:‬‬\n      ‫أوالً‪ :‬انطبــاق بصماتــه كمــا هــو مســجل يف خطــاب األدلــة اجلنائيــة‬\n      ‫ثاني ـاً‪ :‬كــون املدعــى عليــه مــن أربــاب الســوابق ومبــا أن مــا قــام بــه‬\n      ‫املدعــى عليــه فعــل محــرم يســتحق العقــاب عليــه واهلل تعالــى يقــول‪( :‬‬\n      ‫يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n      ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) واهلل تعالــى يقــول ( وال‬\n      ‫تعتــدوا) ولقولــه صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل‬\n      ‫خمــر حــرام) ولقولــه صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم‬\n      ‫حــرام دمــه ومالــه وعرضــه) فلمــا ســبق فقــد حكمــت علــى املدعــى‬\n                                                            ‫عليــه لقــاء ذلــك مبــا يلــي‪:‬‬\n      ‫أوالً‪ :‬إقامــة حــد املســكر عليــه وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n                                      ‫أ مــن النــاس لقــاء شــربه للمســكر‬       ‫أمــام مـ ً‬\n      ‫ثانيــا‪ :‬يســجن املدعــى عليــه ملــدة شــهرين يحتســب منهــا مــا أمضــاه‬\n      ‫موقوفــا يف هــذه القضيــة ويجلــد ثالثــن مكــررة عليــه مرتــن بــن كل‬\n      ‫مــرة وأخــرى مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بــن هــذا اجللــد‬\n      ‫وجلــد احلــد مــدة ال تقــل عــن خمســة عشــر يومــا وذلــك لقــاء مــا نســب‬\n      ‫إليــه مــن الشــبهة لســرقة الســيارة وبعــرض احلكــم علــى الطرفــن قــرر‬\n      ‫املدعــي العــام معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه‬\n      ‫فأفهمتــه باحلضــور يف يــوم األربعــاء املوافــق‪1434/07 /19‬ه ـ الســاعة‬\n      ‫احلاديــة عشــر الســتالم نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه‬\n      ‫خــال مــدة ثالثــن يومــا اعتبــار ًا مــن التاريــخ املشــار إليه فــان مضت املدة‬\n      ‫ولــم يســتلم نســخة مــن احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان‬\n\n\n‫‪275‬‬\n\f‫حقــه يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا كمــا قــرر املدعــى‬\n‫عليــه قناعتــه بــه وجــرى النطــق باحلكــم يف يــوم االثنــن املوافــق‪/17‬‬\n‫‪1434 /07‬ه ـ الســاعة ‪ 10 : 00‬وبــه أقفلــت اجللســة وعلــى ذلــك جــرى‬\n‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                         ‫‪1434/07/17‬هـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬نحــن رئيس وقضاة‬\n‫الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34271212‬وتاريــخ‬\n‫‪1434/7/17‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ .....‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪،.....‬‬\n‫املتهــم يف قضيــة شــرب املســكر وســرقة ســيارة ‪ ،‬احملكــوم فيــه مبــا‬\n‫دون باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                       ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪276‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":271,"source_page_end":276,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d8d9a82157b7790a5ca01a1c001362934da636ba19a52aceac207a4bed0ffa79","normalized_text_hash":"3ba9d6a2e5b91a0e83778268fab024b2cb5bd6f346141cd47c6158d8cb7f2771","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p271-34271212"},{"id":"d51b4498-0b1b-5364-a39e-10a598016177","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -حد املسكر -نظر المحكمة يف وقائع غير مدعى بها ( القفز على منزل ) - انتهاك حرمة منزل -التعزير بالسجن واجللد .","document_number":"34332938","case_number":"34353523","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/18","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -حد املسكر -نظر المحكمة يف وقائع غير مدعى بها ( القفز على منزل ) - انتهاك حرمة منزل -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34332938:‬تاريخه‪1434/10/18:‬هـ‬\n         ‫رقم الدعوى‪ 34353523:‬رقم قرار التصديق‬\n            ‫من محكمة االستئناف‪/3439043:‬ج‪2/‬‬\n                          ‫تاريخه‪1434/12/29:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬حــد املســكر‬\n      ‫‪ -‬نظــر احملكمــة يف وقائــع غيــر مدعــى بهــا ( القفــز علــى منــزل ) ‪-‬‬\n                        ‫انتهــاك حرمــة منــزل ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫املــادة السادســة مــن نظــام اإلجــراءات اجلزائيــة ونصهــا ( وللمحكمــة أن‬\n      ‫تنظــر يف وقائــع غيــر مدعــى بهــا مــن املدعــي العــام ممــا ال يحتــاج إلــى‬\n                                                                            ‫حتقيــق ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وقيــادة‬\n      ‫الســيارة حتــت تأثيــره وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n      ‫املســكر وإفهامــه بــأن عقوبتــه عائــدة للجهــة املختصــة لقــاء قيادتــه‬\n      ‫الســيارة حتــت تأثيــر املســكر ‪،‬حيــث قبــض علــى املدعــى عليــه مــن‬\n      ‫قبــل الدوريــات األمنيــة إثــر بــاغ مــن صاحــب منــزل بقيــام املدعــى عليــه‬\n      ‫بالقفــز علــى منزلــه وباالنتقــال للموقــع شــوهد املدعــى عليــه ولوحــظ‬\n      ‫بأنــه يف حالــة غيــر طبيعيــة وباستشــمامه اتضــح انبعــاث رائحــة املســكر‬\n      ‫مــن جوفه‪،‬صــادق املدعــى عليــه علــى الدعــوى وأضــاف أنــه قــام بالقفــز‬\n      ‫مبنــزل أحــد املواطنــن ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــده‬\n\n‫‪277‬‬\n\f‫حــد املســكر ثمانــن جلــدة دفعــة واحــدة علن ـ ًا ‪ -‬إثبــات إدانتــه بالقفــز‬\n‫علــى منــزل أحــد املواطنــن وتعزيــره بالســجن ملــدة شــهر وجلــده خمســن‬\n‫جلــدة دفعــة واحــدة وإثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر‬\n‫وإفهامــه بــأن عقوبتــه عائــدة للجهــة لولــي األمــر ‪،‬قنــع املدعــى عليــه‬\n‫‪،‬وصــدق احلكــم مــن محكمــة‬        ‫واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة علــى مــن ال نبــي بعــده وبعــد فلــدي أنــا ‪.....‬‬\n‫القاضــي باحملكمــة اجلزائيــة باألحســاء وبنــاء علــى املعاملــة الــواردة إلينا‬\n‫مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم ‪11511‬‬\n‫وتاريــخ ‪1434/07/29‬ه ـ واملقيــدة باحملكمــة برقــم ‪341837915‬‬\n‫وتاريــخ ‪1434/07/30‬ه ـ واحملالــة لــي برقــم ‪ 34353523‬وتاريــخ‬\n‫‪1434/07/30‬ه ـ افتتحــت اجللســة يف يــوم األحــد ‪1434/10/18‬ه ـ‬\n‫يف متــام الســاعة التاســعة والنصــف وفيهــا حضــر املدعــي العــام ‪.....‬‬\n‫املعمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n‫رئيــس دائــرة االدعــاء العــام مبحافظــة األحســاء ذي الرقــم ‪.....‬والتاريــخ‬\n‫‪1434/09/01‬هـ وقال يف دعواه بصفتي مدعي ًا عام ًا يف دائرة االدعاء‬\n‫العــام مبحافظــة األحســاء أدعــي علــى ‪ 25 ،.....:‬عام ـ ًا ‪ ،‬املهنــة أعمــال‬\n‫حــرة ‪ ،‬مســلم الديانــة « ســعودي اجلنســية» مبوجــب الســجل املدنــي رقــم‬\n‫( ‪ ).....‬أوقــف بتاريــخ ‪1434/3/9‬ه ـ ‪ ،‬وأفــرج عنــه بالكفالــة بتاريــخ‬\n‫‪1434/3/10‬ه ـ يقيــم يف محافظــة األحســاء ‪ ،‬حــي ‪.....‬حيــث إنــه بتاريــخ‬\n‫‪1434/3/9‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل رجــال الدوريــات‬\n\n                                                                                     ‫‪278‬‬\n\f      ‫األمنيــة مبحافظــة األحســاء إثــر بــاغ مــن املدعــو ‪ ..... /‬مفــاده قيــام‬\n      ‫املدعــى عليــه بالقفــز علــى منزلــه الواقــع بحــي ‪ (.....‬انتهــى احلــق اخلــاص‬\n      ‫بالتنــازل ) ‪ ،‬وباالنتقــال للموقــع شــوهد املدعــى عليــه ولوحــظ بأنــه‬\n      ‫يف حالــة غيــر طبيعيــة ( ســكر ) وباستشــمامه اتضــح انبعــاث رائحــة‬\n                                                                    ‫املســكر مــن جوفــه ‪.‬‬\n      ‫وبضبــط إفــادة املبلــغ ‪..... /‬أفــاد مبشــاهدته للمدعــى عليــه فــوق ســور‬\n                                                                 ‫اجلــدار األمامــي ملنزلــه ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وشــربه‬\n                 ‫للمســكر ‪ ،‬وقيــادة الســيارة حتــت تأثيــر شــرب املســكر ‪.‬‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بشــرب املســكر ‪ ،‬وقيــادة‬\n      ‫الســيارة حتــت تأثيــره ؛ وذلــك لألدلــة والقرائــن التاليــة ‪ .1 :‬إقــراره املدون‬\n                     ‫علــى الصفحــة رقــم ( ‪ ) 14‬مــن ملــف التحقيــق لفــة رقــم ( ‪) 1‬‬\n      ‫‪ .2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم ( ‪ ) 6‬مــن ملــف‬\n                                                              ‫التحقيــق لفــة رقــم ( ‪. ) 1‬‬\n                                       ‫‪ .3‬محضر القبض املرفق على لفة رقم ( ‪. ) 2‬‬\n      ‫‪ .4‬أقــوال املبلــغ املدونــة علــى الصفحــة رقــم ( ‪ ) 10 ، 9‬مــن ملــف التحقيق‬\n                                                                             ‫لفــة رقــم ( ‪. ) 1‬‬\n      ‫وبالبحــث عمـ ــا إذا كـ ــان لــه سـ ــوابق عثــر ل ــه علــى ســابقة اســتعمال‬\n                                                                    ‫املخــدرات وحيازتــه ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا ؛ أطلــب إثبــات مــا‬\n                                               ‫أســند إليــه ‪ ،‬واحلكــم عليــه باآلتــي ‪:‬‬\n                                                ‫‪ .1‬بعقوبة حد السكر لقاء شربه له ‪.‬‬\n\n\n‫‪279‬‬\n\f‫‪ .2‬إثبــات قيادتــه للســيارة وهــو حتــت تأثيــر شــرب املســكر ‪ ،‬وإفهامــه‬\n‫بــأن عقابــه علــى ذلــك عائــد للجهــة املختصــة اســتنا ًدا للفقــرة ( أو ًال ) مــن‬\n                                                    ‫املــادة ( ‪ ) 68‬مــن نظــام املــرور ‪.‬‬\n‫هــذه دعــواي عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه‬\n‫ا ‪ :‬مــا ذكــره‬      ‫جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـ ً‬\n‫املدعــي العــام مــن شــربي للمســكر وقيادتــي للســيارة حتــت تأثيرهــا‬\n‫فصحيــح وذلــك أننــي شــربت املســكر وقمــت بالقفــز علــى منــزل أحــد‬\n‫املواطنــن ولــم أكــن أي غــرض ســيء وأنــا تائــب ونــادم علــى مــا بــدر‬\n‫منــي وصحيــح نســبة الســابقة لــي وقــد أخــذت محكوميتهــا هكــذا‬\n‫أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪ :‬كــرت‬\n‫ـاء‬\n  ‫ســوابق علــى املدعــى عليــه املتضمــن وجــود ســابقة مخــدرات عليــه فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة بعــد النظــر يف حــال املدعــى عليــه‬\n‫أن‬   ‫والتأكــد مــن أهليتــه وبعــد دراســة أرواق املعاملــة وتأملهــا ومبــا َّ‬\n‫املدعــى عليــه أقـ َّـر بقيــام بالقفــز علــى منــزل أحــد املواطنــن وبنــاء علــى‬\n‫املــادة السادســة مــن نظــام اإلجــراءات اجلزائيــة ونصهــا ‪ « :‬وللمحكمــة‬\n‫تنظــر يف وقائــع غيــر ُمدعــى ِبهــا مــن املُدعــي العــام ِّمــا ال يحتــاج‬    ‫أن ُ‬\n‫أن املدعــى عليــه أقـ َّـر بشــرب املســكر مختــار ًا عاملـ ًا‬  ‫إلــى حتقيــق» ومبــا َّ‬\n‫ـتقر‬\n   ‫بتحرميــه وحـ ُّـد املســكر أن يجلــد صاحبــه ثمانــن جلــدة كمــا اسـ َّ‬\n‫أن املدعــى عليــه‬    ‫ممــا يتوجــب حــد املدعــى عليــه ومبــا َّ‬ ‫عليــه عمــل األمــة َّ‬\n‫أقـ َّـر بقيــادة الســيارة حتــت تأثيــر املســكر وإثبــات قيادتــه حتــت تأثيرهــا‬\n‫لــدى هــذه احملكمــة والعقوبــة لــدى ولــي األمــر حســب األنظمــة املرعيــة‬\n‫التــي ال تتعــارض مــع املصالــح الشــرعية لــذا كلــه وألجــل احلــق العــام‬\n‫حكمــت علــى املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لــدي إدانــة املدعــى‬\n\n\n                                                                                             ‫‪280‬‬\n\f      ‫عليــه بشــرب املســكر مختــارا عاملــا بتحرميــه و يجلــد حــد املســكر‬\n                                                     ‫ثمانــن جلــدة دفعــة واحــدة علنـ ـ ًا ‪.‬‬\n      ‫ثانيـ ًا ‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بالقفــز علــى منــزل أحــد املواطنــن‬\n      ‫وعزرتــه لقــاء ذلــك بســجنه ملــدة شــهر حتتســب منهــا املــدة التــي أوقــف‬\n      ‫فيهــا علــى ذمــة القضيــة وبجلــده خمســون جلــدة دفعــة واحــدة بينــه وبــن‬\n              ‫احلــد مــدة ال تقــل عــن عشــرة أيــام ويكــون جلــد احلــد هــو املقــدم ‪.‬‬\n      ‫ـدي إدانــة املدعى عليه بقيادة الســيارة حتت تأثير املســكر‬             ‫ثالثـاً‪ /‬ثبــت لـ َّ‬\n      ‫ـأن عقوبتــه عائــدة لولــي األمــر وبتــاوة احلكــم علــى الطرفــن‬         ‫وأفهمتــه بـ َّ‬\n      ‫وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر قناعتــه باحلكم وطلب‬\n      ‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم دون الئحــة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‬\n      ‫هــذا وقــد جــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة اخلمــر‬\n      ‫وأثرهــا الســيئ عليــه وعلــى املجتمــع وأقفلــت اجللســة الســاعة العاشــرة‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم وصــدر‬\n                                                         ‫احلكــم يف ‪1434/10 /18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/2478034‬ج‪ 2‬وتاريــخ ‪1434/11/02‬ه ـ‬\n      ‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة األحســاء املكلــف‬\n      ‫برقــم ‪ 341837915‬وتاريــخ ‪1434/10/25‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬املســجل برقــم‬\n      ‫‪ 34332938‬وتاريــخ ‪1434/10/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n      ‫ضــد ‪...../‬يف قضيــة مســكر وقيــادة الســيارة حتــت تأثيرهــا وقــد‬\n\n\n‫‪281‬‬\n\f‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                          ‫‪1434/12/25‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪282‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":277,"source_page_end":282,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"37f8ce0338b2797c28c471895e1223a844e96a688c8811a97ae42d6181c49870","normalized_text_hash":"17909aa8f92515dc9ee9aa340a1f69acc1f946c69d47656b74c1618f28857306","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p277-34332938"},{"id":"1f807321-df56-5190-b548-772960ad39a1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -محاولة دهس شخص -تنازل صاحب احلق اخلاص -إقراره حتقيق ا -رجوع عن اإلقرار بعد احلكم -قبول رجوع املقر عن إقراره -درء احلدود بالشبهات -التعزير بالسجن","document_number":"34332196","case_number":"34439386","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/18","year":"1434","subject":"مسكر -شرب املسكر -محاولة دهس شخص -تنازل صاحب احلق اخلاص -إقراره حتقيق ا -رجوع عن اإلقرار بعد احلكم -قبول رجوع املقر عن إقراره -درء احلدود بالشبهات -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34332196:‬تاريخه‪1434/10/18:‬هـ‬\n                   ‫رقم الدعوى‪34439386:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34352540:‬تاريخه‪1434/11/06:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬محاولــة دهــس شــخص ‪ -‬تنــازل صاحــب احلــق‬\n‫اخلــاص ‪ -‬إقــراره حتقيق ـ ًا ‪ -‬رجــوع عــن اإلقــرار بعــد احلكــم ‪ -‬قبــول‬\n‫رجــوع املقــر عــن إقــراره ‪ -‬درء احلــدود بالشــبهات ‪ -‬التعزيــر بالســجن‬\n                                                                    ‫واجللــد ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( إن دمائكــم وأموالكــم وأعراضكــم‬\n                                                              ‫عليكــم حــرام) ‪.‬‬\n‫‪ -2‬قــول ابــن قدامــة يف املغنــي ‪ (162/9‬وإذا رجــع عــن إقــراره قبــل رجوعــه‬\n           ‫ألنــه حــد هلل ســبحانه فقبــل رجوعــه عنــه كســائر احلــدود ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بشــرب املســكر ومبحاولــة‬\n‫األول دهــس املدعــى عليــه الثانــي وإصابتــه وطلــب إثبــات مــا أســند‬\n‫إليهمــا واحلكــم عليهمــا بحــد املســكر وعقوبــة تعزيريــة مشــددة علــى‬\n‫األول لشــناعة جرمــه حيــث تقــدم املدعــى عليــه الثانــي بشــكوى علــى‬\n‫األول املتضمنــة بأنــه حــاول صدمــه حيــث حضــر املدعــى عليــه األول‬\n‫إلــى الثانــي يف مقــر عملــه واصطحبــه معــه يف الســيارة واجتــه بــه إلــى‬\n‫أحــد الطــرق ثــم توقــف بعــد محطــة الوقــود للتفاهــم معــه حــول مشــكلة‬\n                                                                                   ‫‪290‬‬\n\f      ‫بينهمــا وبنــزول املدعــى عليــه الثانــي مــن الســيارة قــام املدعــى عليــه األول‬\n      ‫بالتحــرك وصــدم املدعــى عليــه الثانــي ثــاث مــرات ‪ ،‬وأثبــت التقريــر‬\n      ‫الطبــي بإصابــة املدعــى عليــه الثانــي برضــوض وجــرح تهتكــي ‪،‬وصادق‬\n      ‫املدعــى عليــه األول بشــرب املســكر وأنكــر الدهــس وأنــه رجــع‬\n      ‫بالســيارة والبــاب مفتــوح واصطــدم بــه البــاب ‪،‬كمــا أنكــر املدعــى‬\n      ‫عليــه الثانــي شــرب املســكر ‪ ،‬بينــة املدعــي العــام هــي التقريــر الطبــي‪،‬‬\n      ‫وإقــرار الطــرف الثانــي بشــرب املســكر يف محضــر املواجهة‪،‬وبنــاء‬\n      ‫علــى مــا تقــدم حكمــت احملكمــة بجلــد املدعــى عليــه األول ثمانــن‬\n      ‫جلــدة حــد املســكر وتعزيــره بســجنه شــهرين لقــاء صدمــه املدعــى عليــه‬\n      ‫الثانــي ‪،‬ورد دعــوى املدعــي العــام بإقامــة حــد املســكر علــى املدعــى‬\n      ‫عليــه الثانــي وبتعزيــره بجلــده ثالثــن جلــدة لقــاء التهمــة ‪،‬قنــع املدعــى‬\n      ‫عليــه األول واعتــرض املدعــي العــام مكتفيــا بالئحــة الدعــوى كمــا‬\n      ‫اعتــرض املدعــى عليــه الثانــي وبعــد إعــان احلكــم رجــع املدعــى عليــه‬\n      ‫األول عــن اإلقــرار بشــرب املســكر ‪،‬وملــا قــرره أهــل العلــم بقبــول رجــوع‬\n      ‫املقــر علــى نفســه باحلــد عــن إقــراره قبــل إقامــة احلــد ‪ ،‬عــدم إثبــات إدانــة‬\n      ‫املدعــى عليــه األول بشــرب املســكر واحلكــم بصــرف النظــر عــن طلــب‬\n      ‫املدعــي العــام بإقامــة حــد املســكر وتعزيــره علــى التهمــة القويــة بجلــده‬\n      ‫تســع ًا وســبعني جلــدة وقنــع املدعــى عليــه باحلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                                 ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪291‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34439386‬وتاريــخ ‪ 1434/10/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 342249950‬وتاريــخ ‪ 1434/09/27‬ه ـ ففــي يــوم‬\n‫األربعــاء ‪ 1434/10/14‬ه ـ فتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ .....‬مدعي ـ ًا علــى احلاضريــن معــه ‪ ..... :‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و ‪ .....‬ســعودي اجلنســية‬\n‫ا يف دعــواه عليهــم ‪ :‬إنــه يف يــوم‬‫مبوجــب الســجل املدنــي (‪ ).....‬قائ ـ ً‬\n‫األحــد املوافــق ‪1434/9/13‬ه ـ تقــدم املواطــن (‪ ).....‬بشــكوى ملركــز‬\n‫شــرطة (‪ ).....‬ضــد املتهــم (‪ ).....‬يدعــي فيهــا بــأن (‪ ).....‬حــاول صدمــه‬\n‫وبســماع أقــوال املتهــم (‪ ).....‬ذكــر أن املتهــم (‪ ).....‬زميلــه (جنــدي أول‬\n‫ويعمــل معــه بنفــس الفرقــة) حضــر لــه مبقــر عملــه ثــم اصطحبــه بســيارة‬\n‫املتهــم (‪ ).....‬مــن نــوع لونهــا بحــري و ســنة صنعهــا (‪2006‬م) واجتــه بــه‬\n‫إلــى طريــق ثــم توقــف بعــد محطــة ‪.....‬بنصــف كيلــو تقريبــا للتفاهــم معــه‬\n‫حــول مشــكلة قدميــة وبنــزول املتهــم (‪ ).....‬قــام املتهــم (‪ ).....‬بالتحــرك‬\n‫والتفحيــط وصــدم املتهــم ‪ .....‬ثــاث مــرات وكانــا بالــزي العســكري‪.‬‬\n‫وبإعــادة ضبــط الشــكوى ذكــر املتهــم ‪ .....‬ذكــر بأنــه يف صبــاح يــوم‬\n‫األحــد املوافــق ‪1434/9/13‬ه ـ كان مبقــر عملــه (بالــزي العســكري)‬\n‫فحضــر إليــه املتهــم ‪(.....‬بالــزي العســكري) وطلــب منــه مرافقتــه‬\n‫فرفــض وأصــر عليــه بركــوب الســيارة وقــال لــه (نبــي نحــط النقــاط‬\n‫علــى احلــروف) فرفــض الركــوب و وقــف املتهــم ‪.....‬بجانــب املتهــم ‪.....‬‬\n\n                                                                                    ‫‪292‬‬\n\f      ‫وكان املتهــم (‪ ).....‬يحــاول إقناعــه بالركــوب معــه بســيارته فركــب‬\n      ‫املتهــم (‪ ).....‬وقــال املتهــم (‪ ).....‬بنــروح نصلــي باملســجد هنــاك أنظــف‬\n      ‫‪ ،‬فتوجــه إلــى طريــق طريــف ولــم يتوقــف عنــد املســجد إلــى أن وصــل‬\n      ‫هجــرة ‪.....‬ثــم عــاد إلــى ثــم رجــع وتوجــه إلــى طريــق حتــى وصــل إلــى ثــم‬\n      ‫رجــع مــرة أخــرى إلــى ثــم عــاد إلــى طريــق واجتــه إلــى طريــق فرعــي ونــزل‬\n      ‫بالســيارة مــع طريــق صحــراوي وبعــد مســافة تقــدر بثالثــة كيلــو متــرات‬\n      ‫توقــف املتهــم (‪ ).....‬وكان يريــد املفاهمــة مــع املتهــم (‪ ).....‬فنــزل املتهــم‬\n      ‫(‪ ).....‬مــن الســيارة فقــام املتهــم (‪ ).....‬بالرجــوع بســيارته وبابهــا مفتــوح‬\n      ‫فصــدم املتهــم (‪ ).....‬ثــم تقــدم املتهــم (‪ ).....‬بســيارته وصــدم املتهــم (‪).....‬‬\n      ‫مــن رجلــه مــرة أخــرى فتمســك املتهــم (‪ ).....‬مبســاحة الســيارة بيــده‬\n      ‫اليمنــى وكان املتهــم ‪.....‬علــى ســرعته وعندمــا توقــف ســقط املتهــم‬\n      ‫(‪ ).....‬ثــم حــاول املتهــم ‪.....‬صــدم املتهــم ‪.....‬مــرة أخــرى فأخــذ املتهــم ‪.....‬‬\n      ‫بيــده تــراب وحصــى وتوجــه إلــى فــوق تــل فأخــذ حجــر ثــم غــادر املتهــم‬\n      ‫‪.....‬املوقــع ‪ .‬وباســتجواب املتهــم ‪ .....‬أقــر باصطحــاب املتهــم ‪ .....‬علــى‬\n      ‫طريــق وذكــر أنــه يف يــوم األحــد املوافــق ‪1434/9/13‬ه ـ خــرج املتهم‪.....‬‬\n      ‫يرافقــه املتهــم ‪ .....‬علــى طريــق ســكاكا ثــم وصــل وعــاد إلــى وكانــوا‬\n      ‫يتناقشــون حــول موضــوع فتوقــف قبــل محطــة ‪ .....‬فنــزل املتهــم ‪.....‬‬\n      ‫وطلــب املتهــم ‪ .....‬مــن املتهــم ‪.....‬الركــوب فرفــض فتحــرك فقــام املتهــم‬\n      ‫‪.....‬برمــي املتهــم ‪.....‬بحجــر فأصابــت الزجــاج األمامــي وبضبــط شــهادة‬\n      ‫الشــاهد ‪ .....‬ذكــر أن املتهــم ‪.....‬اتصــل عليــه صبــاح يــوم األحــد املوافــق‬\n      ‫‪1434/9/13‬ه ـ وطلــب منــه احلضــور إلــى طريــق بالقــرب مــن محطــة ‪.....‬‬\n      ‫وعنــد وصــول الشــاهد إلــى نقطــة تفتيــش ‪ .....‬اتصــل علــى املتهــم ‪.....‬‬\n      ‫وســأله عــن مكانــه حتديــد ًا فقــال املتهــم ‪(.....‬بعــد مــا تتعــدى الرصيــف‬\n\n\n‫‪293‬‬\n\f‫حــق النقطــة خــذ فــوق حتــت تلقانــي واقــف على اليمــن بســيارة ‪ ).....‬فلما‬\n‫وصــل الشــاهد ركــب املتهــم ‪ .....‬بســيارة الشــاهد وذكــر لــه مــا حصــل‬\n‫‪ ،‬كمــا شــاهد وجــود دم علــى الكتــف األميــن للمتهــم ‪ .....‬و متــزق الفنيلــة‬\n‫مــن مــكان الكتــف األميــن ‪ ،‬كمــا ذكــر أن ســيارة املتهــم ‪ .....‬هــي مــن‬\n‫نــوع و لونهــا بحــري ‪.‬ومبعاينــة موقــع احلادثــة وجــدت آثــار تفحيــط و أثريــن‬\n‫علــى شــكل قــوس ‪ .‬ومبعاينــة الســيارة ( اللــون أزرق فــاحت ســنة صنعهــا‬\n‫‪ ، 2006‬حتمــل اللوحــة ‪ ).....‬تبــن وجــود أتربــة وغبــار وكدمــات خفيفــة‬\n‫مــن اجلهــة األماميــة ‪ .‬وبتفريــغ رســالة نصيــة صــادرة مــن الرقــم (‪).....‬‬\n‫إلــى رقــم املتهــم (‪ ).....‬بتاريــخ ‪/23‬يوليــو ‪ ،‬يف متــام الســاعة (‪ 3.27‬ص)‬\n‫كان نصهــا مــا يلــي ‪ :‬الســام عليكــم أو ًال احلمــد هلل علــى الســامة‬\n‫ومــا تشــوف شــر يــا رب وخطــاك الســوء يف البدايــة مقدريــن الضــرر‬\n‫اللــي حصــل ولــم نكــن نتمناهــا أبــد ًا ولكــن طمعانــن يف عفــوك أخــوي‬\n‫أبــو ‪.....‬والعفــو مــن شــيم الرجــال وأنــت رجــال مبعنــى الكلمــة مــن‬\n‫خــال مواقفــك التــي لــن ننســاها مــع أخينــا أبــو ‪.....‬فكلنــا رجــاء بــك‬\n‫أن تعفــو وتصفــح عــن أخينــا وتكــون ســبب ًا يف إصالحــه معنــا ونتعهــد‬\n‫بــأن تكــون هــذه األخيــرة أن لــم يكــن ألجلنــا فمــن أجــل ‪ .....‬و‪ .....‬فهــو‬\n‫عونهــن بعــد اهلل تعالــى وســندهن يف هــذه احليــاة ومــن أجــل الوظيفــة وال‬\n‫يخفــى عليــك صعوبــة احلصــول عليهــا يف زمننــا هــذا كلنــا أمــل يف اهلل‬\n‫تعالــى ثــم بــك لتعفــو ونفتــح صفحــة جديــدة يف حيــاة أخينــا شــاكرين‬\n‫ومقدريــن لــك أو ًال وأخيــرا‪ .‬وبإجــراء املواجهــة بــن املتهــم ‪.....‬واملتهــم ‪،.....‬‬\n‫ذكــر املتهم‪.....‬بــأن املتهــم ‪ .....‬شــرب املســكر بــاألردن فنشــب بينهمــا‬\n‫خــاف وأقــرا بشــربهما املســكر و أصــر كل منهمــا علــى قولــه يف‬\n‫محاولــة الدهــس ولــم يتبــن قــوة حجــة أحدهمــا علــى اآلخــر ولــم يالحــظ‬\n\n\n                                                                                           ‫‪294‬‬\n\f      ‫عليهمــا مــا يســتحق ذكــره وقــد صــدر تقريــر طبــي بحــق املتهــم ‪ .....‬مــن‬\n      ‫مستشــفى عرعــر املركــزي برقــم ‪.....‬وتاريــخ ‪1434/9/15‬ه ـ املتضمــن‬\n      ‫إصابتــه برضــوض بســيطة يف الكتــف األميــن مــن اخللــف وكلتــا اليديــن‬\n      ‫وتهتــك بقيــاس (‪ 5‬ســم) تقريب ـاً‪ ،‬وإصابتــه بجــرح تهتكــي يف الســاق‬\n      ‫األميــن ومــدة الشــفاء ثالثــة أيــام وقــد انتهــى التحقيــق إلــى اتهــام ‪ .....‬و‬\n      ‫‪ .....‬بشــربهما املســكر ‪ ،‬واتهــام ‪ .....‬مبحاولــة دهــس شــخص وإصابتــه‬\n      ‫باإلصابــات املوصوفــة بالتقريــر الطبــي وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا ورد يف محضــر معاينــة موقــع احلادثــة املرفــق لفــة رقــم (‪-2 )29‬‬\n      ‫مــا ورد يف محضــر معاينــة الســيارة املرفــق لفــة رقــم (‪ -3 )30‬مــا ورد‬\n      ‫بالتقريــر الطبــي املرفــق لفــة رقــم (‪ -4 )15‬مــا ورد يف شــهادة الشــاهد‬\n      ‫املدونــة علــى الصفحــة رقــم (‪ )2-1‬مــن املرفــق لفــة رقــم (‪ -5 )22 -21‬مــا‬\n      ‫ورد يف محضــر تفريــغ رســالة نصيــة املرفــق لفــة رقــم (‪ -6 )17‬مــا ورد‬\n      ‫يف محضــر املواجهــة املــدون علــى الصفــح لفــة رقــم (‪ -7 )16‬مــا ورد يف‬\n      ‫أقــوال ‪.....‬املدونــة علــى الصفحــة رقــم (‪ )1‬مــن املرفــق لفــة رقــم (‪)13‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكوريــن وهمــا بكامــل أهليتهمــا املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتهمــا مبــا‬\n      ‫نســب إليهمــا واحلكــم عليهمــا بحــد شــرب املســكر ‪ ،‬واحلكــم علــى‬\n      ‫املتهــم ‪ .....‬بعقوبــة تعزيريــة مشــددة لشــناعة جرمــه ‪( .‬علم ـ ًا بــأن احلــق‬\n      ‫اخلــاص انتهــى بالتنــازل) هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليهمــا أجــاب األول ‪.....‬بقولــه مــا ذكــره املدعــي العــام مــن قيامــي‬\n      ‫بشــرب املســكر صحيــح وبالنســبة مبحاولــة دهــس املدعــى عليــه ‪.....‬‬\n      ‫ثــاث مــرات فغيــر صحيــح والصحيــح أنــه كان راكبـ ًا معــي ونــزل مــن‬\n      ‫الســيارة فرجعــت بالســيارة وبابهــا مفتــوح وصــدم بــه البــاب وســقط علــى‬\n\n\n‫‪295‬‬\n\f‫األرض ثــم طلبــت منــه الركــوب معــي فرفــض ذلــك فذهبــت وتركتــه‬\n‫هكــذا أجــاب وأجــاب املدعــى عليــه الثانــي ‪.....‬بــأن مــا ذكــره املدعــي‬\n‫العــام مــن قيامــي بشــرب املســكر غيــر صحيــح إطالقـ ًا وأضــاف أيضـ ًا‬\n‫بــأن املدعــى عليــه ‪.....‬صديــق لــه وأنــه قــد تنــازل عــن حقــه اخلــاص وأنــه‬\n‫ال خــاف بينهــم هكــذا أضــاف وبســؤال املدعــي العــام عــن بينتــه فيمــا‬\n‫يدعيــه مــن قيــام املدعــى عليــه األول ‪.....‬مــن قيامــه مبحاولــة دهــس‬\n‫املدعــى عليــه ‪.....‬ثــاث مــرات فقــال بينتــي فقــال مــا جــاء يف أوراق‬\n‫املعاملــة وكذلــك مــا جــاء يف إفــادة املدعــى عليــه الثانــي ‪.....‬وكذلــك‬\n‫مــا جــاء بالتقريــر الطبــي املرفــق هكــذا أجــاب وبســؤاله أيض ـ ًا عــن‬\n‫بينتــه علــى مــا يدعيــه مــن قيــام املدعــى عليــه الثانــي ‪.....‬بشــرب املســكر‬\n‫فقــال بينتــي مــا جــاء يف محضــر املواجهــة املرفــق باملعاملــة هكــذا أجاب‬\n‫هــذا وبالرجــوع إلــى محضــر املواجهــة املرفــق باملعاملــة لفــة رقــم(‪)16‬‬\n‫ونــص احلاجــة منــه (وأقــر الطــرف األول بشــرب املســكر واتهــم الثانــي‬\n‫بشــرب املســكر وأقــر الطــرف الثانــي بشــرب املســكر) الطــرف األول‬\n‫‪.....‬توقيعــه الطــرف الثانــي ‪ .....‬توقيعــه وبالرجــوع إلــى التقريــر الطبــي‬\n‫املرفــق باملعاملــة لفــة رقــم (‪ )15‬املتضمــن إصابتــه برضــوض بســيطة‬\n‫يف الكتــف األميــن مــن اخللــف وكلتــا اليديــن وتهتــك بقيــاس (‪ 5‬ســم)‬\n‫تقريبـ ُا ‪ ،‬وإصابتــه بجــرح تهتكــي يف الســاق األميــن ومــدة الشــفاء ثالثــة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى‬\n                                  ‫أيــام مــا لــم حتــدث مضاعفــات انتهــى فبنـ ً‬\n‫واإلجابــة ومــا جــاء مبحضــر املواجهــة بــن الطرفــن وكذلــك مــا جــاء‬\n‫يف التقريــر الطبــي املذكــور وحيــث أقــر املدعــى عليــه األول ‪.....‬بقيامــه‬\n‫بالرجــوع بالســيارة علــى املدعــى عليــه الثانــي وصدمــه إيــاه بالبــاب ولــم‬\n‫يحضــر املدعــي العــام البينــة علــى مــا ذكــره مــن محاولــة دهــس املدعــى‬\n\n\n                                                                                       ‫‪296‬‬\n\f      ‫عليــه ‪.....‬للمدعــى عليــه ‪.....‬ثــاث مــرات وحيــث إن هــذا مــن االعتــداء‬\n      ‫علــى األنفــس املعصومــة بغيــر حــق ولقولــه صلــى اهلل عليــه وســلم (إن‬\n      ‫دمائكــم وأموالكــم وأعراضكــم عليكــم حــرام) متفــق عليــه مــن‬\n      ‫حديــث أبــي بكــرة وملــا جــاء مــن أن املدعــى عليهمــا بينهمــا صحبــة‬\n      ‫وعالقــة حميمــة وقــد تنــازل املدعــى عليــه ‪ .....‬عــن حقــه اخلــاص جتــاه‬\n      ‫املدعــى عليــه ‪.....‬نظــر ًا حلفــظ الــود بينهمــا وحيــث أنكــر املدعــى عليــه‬\n      ‫‪.....‬قيامــه بشــرب املســكر ومــا جــاء يف محضــر املواجهــة بينهمــا يعــد‬\n      ‫قرينــة توجــب توجــه التهمــة لــه بشــرب املســكر لــذا فلــم يثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه األول مبحاولــة دهــس املدعــى عليــه الثانــي ثــاث‬\n      ‫مــرات وإمنــا ثبــت لــدي قيامــه بالرجــوع عليــه وصدمــه بالبــاب مــرة واحــدة‬\n      ‫أثنــاء نزولــه وثبــت لــدي إدانتــه بشــرب املســكر ولــم يثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه الثانــي بشــرب املســكر وإمنــا تتوجــه التهمــة لــه بذلــك‬\n      ‫وحكمــت مبــا يلــي‪ :‬أوالً‪ :‬جلــد املدعــى عليــه األول ثمانــن جلــدة حــد‬\n      ‫املســكر لقــاء شــربه للمســكر ثاني ـ ًا ‪ :‬تعزيــره وذلــك بســجنه ملــدة‬\n      ‫شــهرين وجلــده ســبعني جلــدة لقــاء قيامــه بصــدم املدعــى عليــه الثانــي‬\n      ‫ببــاب الســيارة ثالثـاً‪ :‬ردع طلــب املدعــي العــام إقامــة حــد املســكر علــى‬\n      ‫املدعــى عليــه الثانــي ‪.....‬لعــدم ثبــوت اإلدانــة واالكتفــاء بتعزيــره وذلــك‬\n      ‫بجلــدة ثالثــن جلــدة لقــاء التهمــة بذلــك وبإعــان احلكــم قنــع بــه املدعــى‬\n      ‫عليــه األول ‪.....‬ولــم يقنــع بــه املدعــي العــام وال املدعــى عليــه ‪.....‬وطلبــا‬\n      ‫االســتئناف بــا الئحــة معتبــر ًا املدعــي العــام الئحــة الدعــوى الئحــة‬\n      ‫اعتراضيــة وبعــد إعــان ذلــك قــال املدعــى عليــه ‪.....‬بأننــي لــم أشــرب‬\n      ‫املســكر أبــد ًا وإمنــا أقــررت علــى نفســي ظن ـ ًا منــي بأننــي ســأخرج مــن‬\n      ‫الســجن هكــذا قــال وبنــاء عليــه وحيــث قــرر العلمــاء بــأن مــن أقــر علــى‬\n\n\n‫‪297‬‬\n\f‫نفســه بشــرب مســكر ثــم رجــع عــن إقــراره قبــل إقامــة احلــد عليــه فــإن‬\n‫رجوعــه عــن إقــراره يقبــل ويــدرأ عنــه احلــد قــال ابــن قدامــة يف بــاب شــرب‬\n                   ‫وع ـ ُه؛ ِ َل َّن ـ ُه َحـ ٌّـد ِ َّ ِ‬\n‫ل ُس ـ ْب َحا َن ُه‪،‬‬                                   ‫(و ِإ َذا َر َجـ َـع َعــنْ ْإقـ َـرا ِر ِه قُ ِبــلَ ُر ُج ُ‬\n                                                                                                                  ‫املســكر َ‬\n‫الـ ُـدودِ‪ ) .‬املغنــي ‪ 162/9‬ونظــر ًا إلقــرار‬                         ‫ك َســائ ِِر ْ ُ‬     ‫وع ـ ُه َع ْن ـ ُه‪َ ،‬‬ ‫َف ُق ِبــلَ ُر ُج ُ‬\n‫املدعــى عليــه بشــرب املســكر يف أول اجللســة ثــم رجوعــه عــن إقــراره‬\n‫بعــد احلكــم عليــه ممــا يوجــه التهمــة القويــة لــه بشــرب املســكر لــذا لــم‬\n‫يثبــت لــدي إدانــة املدعــى عليــه ‪.....‬بشــرب املســكر وحكمــت بصــرف‬\n‫النظــر عــن طلــب املدعــي العــام إقامــة حــد املســكر علــى املدعــى عليــه‬\n‫‪.....‬وقــررت تعزيــره بنــاء علــى التهمــة القويــة وذلــك بجلــدة تســع ًا وســبعني‬\n‫جلــدة وبــه حكمــت وبإعــان احلكــم قنــع بــه املدعــى عليــه ‪.....‬وقــررت‬\n‫رفــع املعاملــة حملكمــة االســتئناف مبنطقــة اجلــوف وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                                                      ‫‪ 1434/10/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم‬\n‫‪ 342249950‬وتاريــخ ‪1434/10/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪34332196‬‬\n‫وتاريــخ ‪1434/10/18‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد (‪).....‬‬\n‫ورفيقــه يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫فقــد قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                                     ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                                                                          ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":290,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8c3574cd4c8cbe59be8bf9c2522030f114fd05ba45c4d4e20d85db899638bddf","normalized_text_hash":"cd2e417bbbf74c3742dd0e03e8c9e7095995211ed93f29a9ae3dd383d116562b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p290-34332196"},{"id":"a21e6235-a449-58de-9847-9d41c0b012fd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -إحداث فوضى -التعزير للشبهة -درء حد املسكر -التعزير باجللد .","document_number":"3443649","case_number":"3444662","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"مسكر -شرب املسكر -إحداث فوضى -التعزير للشبهة -درء حد املسكر -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3443649 :‬تاريخه‪1434/2/23:‬هـ‬\n                         ‫رقم الدعوى‪3444662:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34167023‬تاريخه‪1434/3/21 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬إحــداث فوضــى ‪ -‬التعزيــر للشــبهة ‪ -‬درء حــد‬\n                                                     ‫املســكر ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n      ‫‪ .1‬التعزيــر ال يســقط بالشــبهة جــاء يف األشــباه والنظائــر للســيوطي‬\n                                     ‫ص‪ ( 162‬الشــبهة ال تســقط التعزيــر ) ‪.‬‬\n      ‫‪ .2‬قــال ابــن جنيــم يف األشــباه والنظائــر ‪ ( 157‬التعزيــر يثبــت مــع‬\n      ‫الشــبهة ولــذا قالــوا يثبــت مبــا يثبــت بــه املــال ويجــري فيــه احللــف‬\n                                                      ‫ويقضــى فيــه بالنكــول ) ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وإحــداث‬\n      ‫الفوضى بإثارة املشــاكل مع أخيه‪،‬وطلب إثبات ما أســند إليه واحلكم‬\n      ‫عليــه بحــد املســكر وعقوبــة تعزيريــة لقــاء إحــداث الفوضى‪،‬حيــث‬\n      ‫تلقــت الدوريــات األمنيــة بــاغ مــن أحــد املواطنــن بتعرضــه إلطــاق نــار‬\n      ‫مــن شــقيقه املدعــى عليــه وباالنتقــال للموقــع مت القبــض عليــه واتضــح‬\n      ‫وجــود رائحــة تنبعــث مــن املدعــى عليــه وهــو بحالــة غيــر طبيعيــة‪،‬‬\n      ‫وأنكــر املدعــى عليــه الدعــوى ‪ ،‬وكانــت بينــة املدعــي العــام محضــر‬\n      ‫االستشــمام ومحضــر الدوريــات األمنيــة واملثبــت فيــه جتــرد املدعــى‬\n      ‫عليــه مــن مالبســه ماعــدا الســروال وأنــه يف حالــة غيــر طبيعيــة ومحضــر‬\n‫‪299‬‬\n\f‫تعــذر ســماع أقــوال املدعــى عليــه عنــد االســتجواب ألنــه يف حالــة غيــر‬\n‫طبيعية‪،‬وبتوجــه التهمــة القويــة لشــرب املدعــى عليــه املســكر بهــذه‬\n‫القرائــن ‪،‬فقــد حكمــت احملكمــة بتعزيــره باجللــد ســبعني جلــدة دفعــة‬\n‫واحــدة لعــدم ثبــوت إدانــة املدعــى عليــه مبــا جــاء يف الدعــوى ودرء حــد‬\n‫املســكر لعــدم ثبوتــه وصــرف النظــر عــن طلــب املدعــي العــام تعزيــر‬\n‫املدعــى عليــه لقــاء قيامــه بإحــداث الفوضــى وإثــارة املشــاكل مــع أخيــه‬\n‫لعــدم ثبوتــه ‪،‬وقنــع املدعــى عليــه ‪،‬واعتــرض املدعــي العــام بــدون الئحــة‬\n                             ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬    ‫ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 3444662‬وتاريــخ ‪1434/01/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34219112‬وتاريــخ ‪1434/01/25‬ه ـ ففــي يــوم‬\n‫األحد املوافق‪ 1434/02/17‬هـ افتتحت اجللســة الســاعة ‪ 09 : 00‬بشــأن‬\n‫دعــوى املدعــي ‪ .....‬واملكلــف مبهمــة اإلشــراف علــى مكتــب االدعــاء‬\n‫العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس فــرع هيئــة التحقيــق‬\n‫واالدعــاء العــام مبنطقــة جنــران رقــم ‪.....‬وتاريــخ ‪1430/12/29‬ه ـ ضــد‬\n‫ا يف دعــواه‬ ‫‪.....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪.....‬قائ ـ ً‬\n‫عليــه إنــه ورد مبحضــر تنفيــذ املهمــة رقــم (‪).....‬وتاريــخ ‪1434/1/8‬ه ـ‬\n‫املعــد مــن قبــل الدوريــات األمنيــة بنجــران املتضمــن تلقيهــم بــاغ مــن‬\n‫املواطــن ‪.....‬بتعرضــه إلطــاق نــار عليــه داخــل املنــزل مــن قبــل شــقيقه‬\n‫املدعــى عليــه وباالنتقــال للموقــع املذكــور مت القبــض عليــه واتضــح‬\n\n                                                                                    ‫‪300‬‬\n\f      ‫عــدم وجــود أي طلــق نــاري أو ظــروف فارغــة باملوقــع واتضــح وجــود‬\n            ‫رائحــة تنبعــث مــن املدعــى عليــه كمــا أنــه بحالــة غيــر طبيعيــة ‪0‬‬\n      ‫وورد بإعــادة ضبــط أقــوال معــدي محضــر تنفيــذ املهمــة والــذي مضمونــه‬\n      ‫أنــه بتلقيهــم البــاغ انتقــل إلــى املوقــع ضابــط املربــع وانتظــر إلــى حــن‬\n      ‫وصــول الدعــم مــن قبــل رئيــس امليــدان ومت االنتقــال إلــى موقــع احلــادث‬\n      ‫وشــوهد املدعــى عليــه عنــد بــاب بيتــه مــن اخلــارج البس ـ ًا ســرواال‬\n      ‫أبيــض داخلــي فقــط ‪ -‬وهــو يف حالــة غيــر طبيعيــة وباســتدراجه مــن‬\n      ‫ال مــن (‪.....‬و‪.....‬مبنــع رجــال األمــن مــن‬ ‫قبلهــم والقبــض عليــه قــام ك ً‬\n      ‫أخــذ املدعــى عليــه ‪( -‬فــرزت لهــم أوراق بشــأن منعهــم لرجــال األمــن‬\n      ‫مــن أداء عملهــم وأحيلــت لهيئــة الرقابــة والتحقيــق باخلطــاب رقــم ‪.....‬‬\n      ‫وتاريــخ ‪1434/1/11‬ه ـ ) ومت الســيطرة عليهــم ونقلهــم للمركــز‬\n      ‫والعــودة إلــى املدعــى عليــه ونقلــه إلــى املركــز بواســطة أحــد أخوالــه‬\n      ‫بســيارته اخلاصــة وترافقــه الدوريــة األمنيــة وورد باحملضــر املعــد مــن‬\n      ‫قبــل ضابــط خفــر مركــز شــرطة ‪.....‬بتاريــخ ‪1434/1/9‬ه ـ تعذر ســماع‬\n      ‫أقــوال املدعــى عليــه لكونــه يف حالــة غيــر طبيعيــة وتنبعــث منــه رائحــة‬\n      ‫الســكر وباســتجواب املدعــي ‪..... /‬أفــاد بأنــه قــام باإلبــاغ عــن مضاربــة‬\n      ‫وأنــه ال يريــد مواصلــة دعــواه وباســتجواب املدعــى عليــه أفــاد بأنــه بينــه‬\n      ‫وبــن أخيــه املدعــي خالفــات ماليــة وعائليــة أفــرج عــن املدعــى عليــه‬\n      ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة وقــد ورد مبحضــر‬\n      ‫اإلستشــمام بتاريــخ ‪1434/1/9‬ه ـ املعــد مــن قبــل مركــز شــرطة ‪.....‬‬\n      ‫ومنــدوب هيئــة األمــر باملعــروف والنهــي عــن املنكــر اتضــح انبعــاث‬\n      ‫رائحــة مــن فيــه تشــبه رائحــة املســكر وقــد انتهــى التحقيــق إلــى توجيــه‬\n      ‫االتهــام ل ـ ‪..... /‬بشــرب املســكر وإحــداث الفوضــى بإثــارة املشــاكل مــع‬\n\n\n‫‪301‬‬\n\f                                         ‫أخيــه وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n         ‫‪ -1‬ما ورد مبحضر تنفيذ املهمة املنوه عنه واملرفق لفة رقم (‪. )5‬‬\n‫‪ -2‬مــا ورد مبحضــر إعــادة ضبــط معــدي محضــر تنفيــذ املهمــة املنــوه‬\n    ‫عنــه واملــدون ص (‪ )5-4‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪. )24‬‬\n‫‪ -3‬مــا جــاء يف محضــر اإلستشــمام املنــوه عنــه واملــدون ص (‪ )7‬مــن‬\n                  ‫دفتــر محاضــر التحقيــق اجلنائــي املرفــق لفــة رقــم (‪. )1‬‬\n‫‪ -4‬مــا جــاء يف أقــوال املتهــم املنــوه عنهــا واملدونــة ص (‪ )7-6‬مــن دفتــر‬\n                                                ‫التحقيــق املرفــق لفــة رقــم (‪. )24‬‬\n‫‪ -5‬مــا ورد مبحضــر تعــذر ســماع األقــوال املنــوه عنــه واملــدون ص (‪ )8‬مــن‬\n                       ‫دفتــر محاضــر التحقيــق اجلنائــي املرفــق لفــة رقــم (‪. )1‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه‪..... /‬وهــو بكامــل قــواه العقليــة‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n                                                       ‫إليــه واحلكــم عليــه باآلتــي‪:‬‬\n                                         ‫‪ -1‬عقوبة حد املسكر لقاء شربه له ‪.‬‬\n‫‪ -2‬عقوبــة تعزيريــة لقــاء إحــداث املشــاكل وإثــارة الفوضــى تردعــه‬\n                                                                      ‫وتزجــر غيــره ‪.‬‬\n‫وبــاهلل التوفيــق هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه‬\n‫قــال مــا ذكــره املدعــي العــام مــن قيامــي بشــرب املســكر فهــو غيــر‬\n‫ا ومــا ذكــره مــن قيامــي بإحــداث الفوضــى‬             ‫صحيــح جملــة وتفصي ـ ً‬\n‫بإثــارة املشــاكل مــع أخــي فهــو غيــر صحيــح والصحيــح هــو أنــي كنـ ُـت‬\n‫أطلــب حقــي مــن إرث والــدي الــذي اغتصبــه أخــي ولــم أقــم باالعتــداء‬\n‫عليــه مطلق ـ ًا هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي العــام هــل‬\n‫لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد لــدي بينــة ســوى مــا‬\n\n\n                                                                                          ‫‪302‬‬\n\f      ‫جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق واالطــاع علــى‬\n      ‫محضــر االستشــمام املــدون علــى ص ‪ 7‬مــن امللــف املرفــق علــى لفــة رقــم‬\n      ‫‪ 1‬وعلــى محضــر تعــذر ســماع األقــوال املــدون علــى ص ‪ 8‬مــن ذات امللــف‬\n      ‫كمــا جــرى منــي االطــاع علــى أقــوال معــدي محضــر الدوريــات األمنيــة‬\n      ‫ـاء علــى مــا‬\n                 ‫املدونــة علــى ص ‪ 5-4‬مــن امللــف املرفــق علــى لفــة رقــم ‪ 24‬فبنـ ً‬\n      ‫ســبق مــن الدعــوى واإلجابــة وحيــث إن املدعــى عليــه قــد أنكــر قيامــه‬\n      ‫بشــرب املســكر ولــم يعتــرف بذلــك حتقيقـ ًا وألن محضــر االستشــمام‬\n      ‫لــم يتضمــن ســوى شــهادة عضــو واحــد مــن أعضــاء هيئــة األمــر باملعــروف‬\n      ‫والنهــي عــن املنكــر ولتوجــه التهمــة القويــة علــى املدعــى عليــه بشــربه‬\n                                                 ‫املســكر املؤيــدة بالقرائــن اآلتيــة‪:‬‬\n      ‫‪ -1‬مــا جــاء يف محضــر االستشــمام املتضمــن بأنــه بعــد استشــمام رائحــة‬\n      ‫فــم املدعــى عليــه مــن قبــل عضــو هيئــة األمــر باملعــروف والنهــي عــن‬\n                                        ‫املنكــر تبــن انبعــاث رائحــة املســكر منــه‬\n      ‫‪ -2‬مــا جــاء يف محضــر تعــذر ســماع األقــوال املتضمــن بأنــه قــد تعــذر‬\n      ‫اســتجواب املدعــى عليــه ألنــه يف حالــة غيــر طبيعيــة وتنبعــث منــه رائحــة‬\n                                                                                ‫املســكر‬\n      ‫‪ -3‬مــا جــاء يف أقــوال معــدي محضــر الدوريــات األمنيــة املتضمــن بأنهمــا‬\n      ‫شــاهدا املدعــى عليــه متجــرد ًا مــن مالبســه وليــس عليــه إال ســروال‬\n      ‫أبيــض طويــل وهــو يف حالــة غيــر طبيعيــة ويهــذي وملــا كان مــن املقــرر‬\n      ‫فقهـ ًا أن التعزيــر ال يســقط بالشــبهة قــال جــال الديــن الســيوطي رحمــه‬\n      ‫اهلل‪ « :‬الشــبهة ال تســقط التعزيــر» ( األشــباه والنظائــر ‪ -‬ص ‪) 162‬‬\n      ‫ويقــول ابــن جنيــم رحمــه اهلل‪ « :‬التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا‬\n       ‫يثبــت مبــا يثبــت بــه املــال ويجــري فيــه احللــف ويقضــى فيــه بالنكــول»‬\n\n\n‫‪303‬‬\n\f‫( األشــباه والنظائــر ‪ -‬ص ‪ ) 157‬وحيــث إنــه لــم يثبــت قيــام املدعــى عليــه‬\n‫باالعتــداء علــى أخيــه وألن وجــود مشــكلة بــن املدعــى عليــه وبــن أخيــه‬\n‫ال يعــد مســوغ ًا لتعزيــره مــا لــم يثبــت كيديــة شــكواه عليــه وتأسيس ـ ًا‬\n‫علــى جميــع مــا ســبق فقــد قــررت مــا يأتــي أو ًال ‪ :‬لــم يثبــت لــدي إدانــة‬\n‫املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ثانيـ ًا ‪ :‬درء حــد املســكر‬\n‫عــن املدعــى عليــه لعــدم ثبــوت موجبــه ثالثـ ًا ‪ :‬تعزيــر املدعــى عليــه وذلــك‬\n‫بجلــده ســبعني جلــدة علن ـ ًا دفعــة واحــدة لقــاء توجــه التهمــة القويــة إليــه‬\n‫بتعاطــي املســكر رابع ـ ًا ‪ :‬صرفــت النظــر عــن مطالبــة املدعــي العــام‬\n‫بتعزيــر املدعــى عليــه لقــاء قيامــه بإحــداث الفوضــى بإثــارة املشــاكل‬\n‫مــع أخيــه لعــدم ثبــوت موجبــه هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليــه قنــع بــه كمــا قــرر املدعــي العــام اعتراضــه‬\n‫بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n             ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/17‬ه ـ الســاعة ‪09:30‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة بنجــران‬\n‫برقــم ‪ 34219112‬وتاريــخ ‪1434/3/8‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 3443649‬وتاريــخ‬\n‫‪1434/2/23‬ه ـ اخلــاص بدعــوى املدعــي العــام ضـ ــد ‪..... /‬يف قضيــة (‬\n‫شــرب املســكر وإحــداث الفوضــى ) علــى الصفــة املوضحــة يف القــرار‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n               ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                        ‫‪304‬‬\n\f305\n\f306\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":299,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b1290b10301aa62afe9acc5d37e85451d3704df23f06f4aa28f9bdcd1f7ef464","normalized_text_hash":"6184cc60a0d803c38f5f7003817d55527e52988c2517ba2ac3ef628c87cd8a48","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p299-3443649"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e8bae93b-82a8-5ac7-8f69-8372b93994a0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -إقرار حتقيق ا -قبول الرجوع عن اإلقرار يف احلدود -تعزير للشبهة - احلدود تدرأ بالشبهات -التعزير باجللد .","document_number":"34263206","case_number":"34292127","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -إقرار حتقيق ا -قبول الرجوع عن اإلقرار يف احلدود -تعزير للشبهة - احلدود تدرأ بالشبهات -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫رقم الصك‪ 34263206:‬تاريخه‪1434/7/9:‬هـ‬\n                        ‫رقم الدعوى‪34292127:‬‬\n                  ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34284484:‬تاريخه‪1434/8/01:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬إقــرار‬\n      ‫حتقيق ـ ًا ‪ -‬قبــول الرجــوع عــن اإلقــرار يف احلــدود ‪ -‬تعزيــر للشــبهة ‪-‬‬\n                               ‫احلــدود تــدرأ بالشــبهات ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n      ‫رجــوع املقــر عــن إقــراره مقبــول عنــد عامــة الفقهــاء قــال صاحــب الشــرح‬\n      ‫( ومتــى رجــع املقــر باحلــد عــن إقــراره قبــل منــه وإن رجــع يف أثنــاء احلــد‬\n      ‫لــم يتمــم وجملــة ذلــك أن شــرط إقامــة احلــد باإلقــرار البقــاء عليــه‬\n          ‫إلــى متــام احلــد فــإن رجــع عــن إقــراره كــف عنــه ) قــال يف اإلنصــاف‬\n                                  ‫(هذا املذهب يف جميع احلدود)‪. 207-206/26‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وقيادة الســيارة‬\n      ‫حتــت تأثيــر املســكر ‪،‬وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بحــد املســكر وإفهامــه بــأن عقوبتــه لقــاء قيــادة الســيارة حتــت تأثيــر‬\n      ‫املســكر عائــدة للجهــة املختصــة ‪،‬وحيــث جــرى اســتيقاف املدعــى عليــه‬\n      ‫مــن قبــل الدوريــة األمنيــة وتبــن أنــه بحالــة غيــر طبيعيــة ‪،‬وباستشــمامه‬\n      ‫اتضــح انبعــاث رائحــة مــن أنفاســه تشــبه رائحــة املســكر ‪،‬وقــد أنكــر‬\n      ‫املدعــى عليــه الدعــوى ‪،‬وكانــت بينــة املدعــي العــام إقــرار املدعــى‬\n\n‫‪245‬‬\n\f‫عليــه حتقيقـ ًا بشــرب املســكر ومحضــر االستشــمام ‪،‬ولرجــوع املدعــى‬\n‫عليــه عــن إقــراره ‪،‬ومبــا أن شــهادة الشــهود ليــس فيهــا جــزم بانبعــاث‬\n‫املســكر ‪،‬وإقامــة حــد املســكر علــى الرائحــة مختلــف فيــه عنــد أهــل‬\n‫‪،‬ولتوجــه التهمــة القويــة عليــه‬\n                            ‫ّ‬      ‫العلــم ‪،‬ومبــا أن احلــدود تــدرأ بالشــبهات‬\n‫حكمــت احملكمــة بتعزيــره بجلــده تســع ًا وســبعني جلــدة دفعــة واحــدة‬\n‫‪،‬وقنــع املدعــى عليــه باحلكــم ‪،‬واعتــرض املدعــي العــام بــدون الئحــة‬\n                              ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬  ‫ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34292127‬وتاريــخ ‪1434/06/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341534966‬وتاريــخ ‪ 1434/06/25‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/07/08‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n‫وفيهــا حضــر املدعــي العــام وقــدم الئحــة دعــواه ضد ‪.....‬ســعودي اجلنســية‬\n‫ا ‪ :‬إنــه بتاريــخ ‪1434/6/8‬ه ـ‬  ‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائ ـ ً‬\n‫يف متــام الســاعة (‪ )10.27‬مــن مســاء يــوم اخلميــس أثنــاء اســتالم دوريــة‬\n‫األمــن بســوق ‪.....‬حضــر إليهــم املتهــم مدعيـ ًا علــى أشــخاص مــن اجلنســية‬\n‫اليمنيــة وباســتيقافه تبــن أنــه بحالــة غيــر طبيعيــة وباستشــمامه اتضــح‬\n‫انبعــاث رائحــة مــن أنفاســه تشــبه رائحــة املســكر وباســتجواب املتهــم‬\n‫أقــر بشــرب املســكر ‪ ،‬وقــد أثبــت تقريــر فحــص عينــة دم املتهــم‬\n‫الصــادر مــن جلنــة حتــري الكحــول باملستشــفى برقــم (‪ ).....‬وتاريــخ‬\n‫‪1434/6/14‬ه ـ إيجابيــة العينــة ملــادة الكحــول ‪ ،‬وقــد انتهــى التحقيــق‬\n                                                                                   ‫‪246‬‬\n\f      ‫إلــى اتهــام‪..... /‬بشــرب املســكر وقيــادة الســيارة حتــت تأثير املســكر‪،‬‬\n      ‫وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا لــذا اطلــب إثبــات إدانتــه مبــا أســند‬\n      ‫إليــه واحلكــم عليــه بحــد شــرب املســكر واثبــات إدانتــه بقيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر وإفهامــه بــان عقابــه عائــد للجهــة املختصــة وفقــا‬\n      ‫للمــادة (‪ )1/1/74‬مــن نظــام املــرور والئحتــه التنفيذيــة‪ .‬ويف نفــس‬\n      ‫اجللســة حضــر املدعــى عليــه فجــرى ســؤاله عمــا جــاء يف الئحــة املدعــي‬\n      ‫ا ‪ :‬كل مــا جــاء يف الئحــة املدعــي العــام مــن شــربي‬       ‫العــام فأجــاب قائـ ً‬\n      ‫للمســكر وقيادتــي الســيارة حتــت تأثيــره غيــر صحيــح هكــذا أجــاب‪،‬‬\n      ‫ا ‪ :‬بينتــي مــا جــاء بإقــرار‬‫ثــم ســألت املدعــي العــام عــن بينتــه فأجــاب قائـ ً‬\n      ‫املدعــى عليــه حتقيقـ ًا واملــدون علــى لفــة (‪ )10‬صفحــة (‪ )3‬وهــذا نصــه ‪:‬‬\n      ‫(أقــر أنــا ‪.....‬أنــي قمــت بتنــاول املســكر) ‪ ،‬ومــا جــاء يف محضــر القبــض‬\n      ‫واالستشــمام لفــة (‪ )2‬واملتضمــن ‪( :‬واتضــح انبعــاث رائحــة كريهــة منــه‬\n      ‫تشــبه رائحــة املســكر) ‪ ،‬ومــا جــاء بتقريــر جلنــة حتــري الكحــول لفــة‬\n      ‫(‪ )11‬واملتضمــن إيجابيــة عينــة دم املدعــى عليــه للكحــول ‪ ،‬وبعــرض‬\n      ‫ا ‪ :‬ال صحــة ملــا جــاء يف كالم‬        ‫ذلــك علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫املدعــي العــام ‪ ،‬أمــا اإلقــرار فصحيــح أنــه صــدر منــي ولكنــه حتــت‬\n      ‫وطــأة التهديــد واإلكــراه هكــذا أجــاب ‪ ،‬فســألت املدعــي العــام هــل‬\n      ‫ا ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‬    ‫لديــك زيــادة بينــة فأجــاب قائـ ً‬\n      ‫ا ‪ :‬ال ســوابق علـ ّـي‬  ‫‪ ،‬وســألت املدعــى عليــه عــن ســوابقه فأجــاب قائ ـ ً‬\n      ‫وهلل احلمــد فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وإلنــكار‬\n      ‫ا ‪ ،‬ولرجوعــه عــن إقــراره‬       ‫املدعــى عليــه مــا نســب إليــه جملــة وتفصي ـ ً‬\n      ‫املثبــت حتقيق ـ ًا واملذكــور أعــاه والرجــوع عــن اإلقــرار يف احلــدود‬\n\n\n‫‪247‬‬\n\f‫مقبــول عنــد عامــة الفقهــاء قــال صاحــب الشــرح ( ومتــى رجــع املقــر‬\n‫باحلــد عــن إقــراره قبــل منــه وإن رجــع يف أثنــاء احلــد لــم يتمــم وجملــة‬\n‫ذلــك أن شــرط إقامــة احلــد باإلقــرار البقــاء عليــه إلــى متــام احلــد فــإن‬\n‫رجــع عــن إقــراره كــف عنــه ) قــال صاحــب اإلنصــاف ( هــذا املذهــب‬\n‫يف جميــع احلــدود ) ‪ ، 2080207/26‬وملــا جــاء بتقريــر جلنــة حتــري‬\n‫الكحــول املذكــور أعــاه ‪ ،‬ولكــون شــهادة الشــهود املدونــة بعاليــه‬\n‫ـاء‬\n ‫ليــس فيهــا اجلــزم بانبعــاث رائحــة املســكر و إقامــة حــد املســكر بنـ ً‬\n‫علــى الرائحــة عنــد اجلــزم بهــا مختلــف فيــه عنــد أهــل العلــم فعنــد عــدم‬\n‫اجلــزم مــن بــاب أولــى ‪ ،‬وألن احلــدود تــدرأ بالشــبهات ‪ ،‬ولعــدم وجــود‬\n‫ســوابق جنائيــة علــى املدعــى عليــه وجلميــع مــا تقــدم فلــم يثبــت لــدي‬\n‫إدانــة ‪.....‬بشــرب املســكر وقيادتــه الســيارة حتــت تأثيــره ورددت طلــب‬\n‫املدعــي العــام إقامــة حــد املســكر ‪ ،‬ولكــن لتوجــه التهمــة القويــة عليــه‬\n‫فقــد قــررت تعزيــره بجلــده تســعة وســبعني جلــدة دفعــة واحــدة وبذلــك‬\n‫حكمــت وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة باحلكــم وقــرر‬\n‫املدعــي العــام املعارضــة بــدون الئحــة وعليــه فقــد قــررت رفــع املعاملــة‬\n‫إلــى محكمــة االســتئناف كاملتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/08‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف باجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر بالنيابــة‬\n‫برقم‪341534966‬وتاريخ‪1434/7/11‬هـ ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشيخ‪...../‬املســجل برقــم ‪34263206‬يف‪1434/7/9‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضد‪...../‬التهامــه بشــرب املســكر وقــد‬\n\n\n                                                                                     ‫‪248‬‬\n\f      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة‪ .‬تقــرر املصادقــة علــى احلكــم‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪249‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":245,"source_page_end":249,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"49c45f3f5d4c5bf3377bcdc9dab009d140d454cc96521b31e7440fdde88a3165","normalized_text_hash":"b55cfbe6a69b5e340b11681c04ad9f0f362f962662328fb586510981f44adf70","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p245-34263206"},{"id":"5162cf01-a53c-5763-a713-4120caa91a8e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر وحيازته -قيادة سيارة حتت تأثير املسكر -حد املسكر -هروب من رجال األمن -التعزير بالسجن واجللد .","document_number":"34263461","case_number":"34308172","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"مسكر -شرب املسكر وحيازته -قيادة سيارة حتت تأثير املسكر -حد املسكر -هروب من رجال األمن -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34263461 :‬تاريخه‪1434/7/9:‬هـ‬\n                        ‫رقم الدعوى‪34308172 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34297697‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر وحيازتــه ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر‪ -‬حــد‬\n              ‫املســكر ‪ -‬هــروب مــن رجــال األمــن ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n      ‫‪ -2‬عــن ابــن عمــر رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قــال ( لعــن اهلل اخلمــر وشــاربها وســاقيها ومبتاعهــا وبائعهــا وعاصرهــا‬\n                   ‫ومعتصرهــا وحاملهــا واحملمولــة إليــه ) أخرجــه أبــوداود ‪.‬‬\n      ‫‪ -3‬عــن ابــن عبــاس رضــي اهلل عنهمــا قــال ســمعت رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم يقــول ( أتانــي جبريــل فقــال يــا محمــد إن اهلل لعــن اخلمــر‬\n      ‫وعاصرهــا ومعتصرهــا وشــاربها واحملمولــة إليــه وبائعهــا ومبتاعهــا‬\n      ‫وساقيها ومسقيها ) أخرجه أحمد وابن حبان يف صحيحه واحلاكم‪.‬‬\n      ‫‪ -4‬عــن ابــن عمــر رضــي اهلل عنهمــا أن رســول اهلل صلــى اهلل عليــه وســلم‬\n      ‫قــال ( ثالثــة حــرم اهلل تبــارك وتعالــى اجلنــة مدمــن اخلمــر والعــاق‬\n                                        ‫والديــوث الــذي يقــر يف أهلــه اخلبــث ) ‪.‬‬\n      ‫‪ -5‬عــن جابــر بــن عبــداهلل رضــي اهلل عنــه أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم قال ( كل مســكر خمر إن اهلل عهد ملن يشــرب املســكر أن يســقيه‬\n                       ‫اهلل مــن طينــة اخلبــال ‪ )..‬أخرجــه مســلم يف صحيحــه ‪.‬‬\n      ‫‪ -6‬ذكــر ابــن القيــم يف زاد املعــاد ‪ ( 42/5‬ويف مصنــف عبدالــرزاق أنــه‬\n‫‪263‬‬\n\f                      ‫صلــى اهلل عليــه وســلم جلــد يف اخلمــر ثمانــن ) ‪.‬‬\n‫‪ -7‬ذكــر املــرداوي يف اإلنصــاف ‪ ( 422 -421/26‬ومــن شــربه مختــار ًا‬\n‫ا كان أو كثيــر ًا فعليــه احلــد ثمانــون‬ ‫عامل ـ ًا أن كثيــره يســكر قلي ـ ً‬\n‫جلــدة وهــذا املذهــب ‪ ،‬وعليــه جماهيــر األصحــاب وجــزم بــه اخلرقــي‬\n                                                           ‫وابــن عقيــل ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بشــرب املســكر وحيازتــه‬\n‫ومحاولــة الهــروب مــن رجــال األمــن واتهــام األول بقيــادة الســيارة حتــت‬\n‫تأثيــر املســكر واالعتــداء علــى مركبــة رســمية ‪،‬وطلب إثبات ما أســند‬\n‫إليهمــا واحلكــم عليهمــا بحــد املســكر وتعزيرهمــا لقاء ما أســند إليهما‬\n‫وإثبــات إدانــة املدعــى عليــه األول لقــاء قيادتــه حتــت تأثيــر املســكر‬\n‫وتشــديد العقوبــة عليــه وفــق األنظمــة والتعليمــات ‪،‬حيــث كان املدعــى‬\n‫عليــه يقــود ســيارته بســرعة جنونيــة فقــام باالرتطــام بســيارة الدوريــة‬\n‫وارتكــب الفــرار ممــا أدى إلــى ارتطامــه بســيارة أخــرى فتــم ضبــط‬\n‫املدعــى عليهمــا بعــد محاولتهمــا الهــرب علــى أقدامهــم ومعهمــا شــخص‬\n‫آخــر فــرزت لــه أوراق مســتقلة كمــا وجــد قــارورة بهــا مــادة مســكره‬\n‫‪،‬وحضــر املدعــى عليــه األول ولــم يحضــر الثانــي ‪،‬وصــادق علــى الدعوى‬\n‫ماعــدا االعتــداء علــى املركبــة الرســمية واصطدامــه بهــا فأنكــر ذلــك‬\n‫وأنهــا هــي مــن ارتطمــت بــه مــن اخللــف ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بجلــده ثمانــن جلــدة دفعــة واحــدة حــد املســكر وصــرف‬\n‫النظــر عمــا طلبــه املدعــي العــام مــن تعزيــره علــى الكميــة التــي معــه‬\n‫وذلــك لقلتهــا ولعــدم توفــر موجبــه وإفهــام املدعــى عليــه بــأن عقوبتــه على‬\n                                                                                     ‫‪264‬‬\n\f      ‫قيــادة الســيارة حتــت تأثيــر املســكر لولــي األمــر وســجن املدعــى عليــه‬\n      ‫مــدة ســتة أشــهر الصطدامــه بســيارة الدوريــة ومحاولــة الهــرب وجلــده‬\n      ‫مائــة جلــدة مفرقــة علــى دفعتــن كل دفعــة خمســن ‪،‬وبالنســبة للمدعى‬\n      ‫عليــه الثانــي فتبقــى قضيتــه وتفــرز لــه أوراق مســتقلة ألن املدعــى عليــه‬\n      ‫األول ســجني ‪،‬وقنــع املدعــى عليــه ‪،‬واعتــرض املدعــي العــام مكتفي ـ ًا‬\n                ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬  ‫بالئحــة الدعــوى ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 34308172‬وتاريــخ ‪1434/07/04‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341613287‬وتاريــخ ‪1434/07/04‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافق‪1434/07/09‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 15‬‬\n      ‫للنظــر يف الدعــوى املرفوعــة مــن املدعــي العــام ضــد ‪.....‬و‪.....‬بطلــب‬\n      ‫إثبــات الهــروب وإيقــاع حــد املســكر وفيهــا حضــر املدعــي العــام ‪.....‬‬\n      ‫وادعــى علــى احلاضــر معــه ‪.....‬يحمــل ســجل مدنــي رقــم (‪).....‬موقــوف‬\n      ‫قائــا يف دعــواه بتاريــخ ‪1434/6/15‬ه ـ تســلم مركــز الشــرطة تقريــر‬\n      ‫إحــدى فــرق الدوريــات األمنيــة رقــم (‪ ).....‬املتضمــن أثنــاء قيــام الفرقــة‬\n      ‫بعملهــا علــى شــارع ‪.....‬اصطدمــت مبركبتهــم الرســمية ســيارة نــوع‬\n      ‫حتمــل اللوحــة رقــم (‪ ).....‬يقودهــا املدعــى عليــه ‪.....‬وكانــت تســير‬\n      ‫بســرعه جنونيــه فقــام باالرتطــام بســيارة الدوريــة وارتكــب الفــرار ممــا‬\n      ‫أدى إلــى ارتطامــه بســيارة أخــرى وضبــط املدعــى عليهمــا أعــاه بعــد‬\n      ‫محاولتهــم الهــرب علــى أقدامهــم ومعهمــا شــخص يدعــى ‪ (.....‬مت فــرز‬\n‫‪265‬‬\n\f‫أوراق مســتقله للقبــض عليــه) ووجــد قــارورة مــاء صحــة بهــا الربــع مــن‬\n‫مــادة مســكره‪ .‬وورد تقريــر املــرور املتضمــن أن نســبة اخلطــأ ‪ %100‬علــى‬\n‫املدعــى عليــه ‪...../‬ومت إعــداد محضــر باستشــمام املذكوريــن وتبــن‬\n‫انبعــاث رائحــة املســكر مــن فيهمــا‪ .‬وبســماع أقــوال رجــل األمــن‪...../‬‬\n‫أفــاد انــه أثنــاء قيامــه بعملــه ويرافقــه رجــل األمن‪...../‬علــى شــارع ‪.....‬‬\n‫ارتطمــت بهمــا الســيارة املوصوفــة أعــاه مــن جهــة الرفــرف األمامــي‬\n‫األميــن وارتكــب الفــرار وكان بالســيارة ثالثــة أشــخاص وهــم املدعــى‬\n‫عليهمــا املذكوريــن وكان يقــود الســيارة املتهــم‪..... /‬و معهــم شــخص‬\n‫يدعــى ‪.....‬وبســماع أقــوال رجــل األمــن‪ ........../‬أفــاد بانــه أثنــاء عملــه‬\n‫مرافــق للعســكري ‪ .....‬قامــت الســيارة املذكــور أوصافــه أعــاه‬\n‫باالرتطــام بســيارة الدوريــة األمنيــة ثــم ارتكــب الفــرار ومت القبــض علــى‬\n‫املدعــى عليهمــا املذكوريــن أعــاه ويقــود الســيارة املدعــى عليــه‪...../‬‬\n‫وباســتجواب املدعــى عليــه ‪...../‬اقــر بشــرب املســكر و بقيــادة الســيارة‬\n‫حتــت تأثيــر املســكر وباالرتطــام بســيارة دوريــة امنيــه والهــروب مــن‬\n‫الدوريــات األمنيــة وحيــازة املســكر وأضــاف أنــه كان هــارب مــن‬\n‫ســيارة دوريــة أمنيــة أخــرى غيــر التــي ارتطــم بهــا وأن ســيارة الدوريــة‬\n‫اعترضتــه وهــو يقــود ســيارته فارتطــم بهــا وأضــاف أن املدعــو ‪...../‬ال‬\n‫يعرفــه إمنــا ركــب معهمــا لغــرض توصيلــه وليــس لــه عالقــة بالقضيــة ‪.‬‬\n‫وباســتجواب املتهــم ‪...../‬أفــاد انــه كان راكــب مــع املدعــى عليــه‪...../‬‬\n‫وانهمــا كانــا يشــربان املســكر وقامــت دوريــة أمنيــة مبحاولــة إيفاقهمــا‬\n‫فهــرب املدعــى عليــه ‪.....‬بســيارته وارتطــم بدوريــة أمنيــة ملــا أشــير إليــه‬\n‫اقــرر اتهــام األول‪ .......... /‬و الثاني‪...../‬بشــرب املســكر وحيازتــه واتهــام‬\n‫األول ‪ .....‬بقيــادة الســيارة حتــت تأثيــره واالعتــداء علــى مركبــة رســمية‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫واتهــام األول والثانــي‪ /‬مبحاولــة الهــرب مــن رجــال األمــن ‪.‬وذلــك لألدلــة‬\n                                                                        ‫والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا ورد بأقــوال املدعــى عليهمــا املنــوه عنهــا واملدونــة علــى اللفــة رقــم‬\n                                                                                         ‫( )‪.‬‬\n                 ‫‪ -2‬ما ورد بتقرير الدوريات األمنية املنوه عنه واملدون لفه (‪.)5‬‬\n                       ‫‪ -3‬ما ورد يف تقرير املرور املنوه عنه واملرفق لفه رقم (‪.)3‬‬\n      ‫‪ -4‬مــا ورد يف محضــر االستشــمام املنــوه عنــه واملــدون علــى اللفــة رقــم‬\n      ‫(‪ .)1‬وحيــث إن مــا أقــدم عليــه املذكــوران فعــل معاقــب عليــه شــرعا لــذا‬\n      ‫اطلــب بعقوبــة حــد املســكر وتعزيرهمــا لقــاء مــا أســند إليهمــا وللمدعــى‬\n      ‫عليــه ‪.....‬النظــر فيمــا يتعلــق بقيادتــه للســيارة حتت تأثير شــرب املســكر‬\n      ‫املعاقــب علــى ذلــك مبوجــب الفقــرة الثانيــة مــن املــادة (‪ )68‬مــن املرســوم‬\n      ‫امللكي رقم (م‪ )85/‬وتاريخ ‪1428/10/26‬هـ وتشديد العقوبة استنادا‬\n      ‫لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )36717‬وتاريــخ ‪1431/6/11‬ه ـ‬\n      ‫‪،‬علمــا بانــه مت تســديد تلفيــات الدوريــة األمنيــة البالــغ قيمتهــا (‪)7000‬‬\n      ‫ريــال‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه عن دعــوى املدعي العام أجاب‬\n      ‫قائــا كلمــا ذكــره املدعــي العــام مــن قيامــي بقيــادة ســيارة مــن نــوع‬\n      ‫وهــي حتمــل اللوحــة التــي ذكرهــا فهــذا كلــه صحيــح وأمــا مــا ذكــره‬\n      ‫مــن أننــي ارتطمــت بالدوريــة فليــس بصحيــح والصحيــح بــأن ســيارة‬\n      ‫الدوريــة قــد طلبــت منــي التوقــف فلــم اســتجب فاصطدمت بــي من اخللف‬\n      ‫ممــا أدى إلــى صدمــي بالســيارة األماميــة وقــد شــربت املســكر وكان‬\n      ‫بحوزتــي ربــع قــارورة صغيــره بهــا مســكر ولــم أهــرب مــن املــكان وأنــا‬\n      ‫مخطــئ ونــادم وكنــت اقــود الســيارة وأنــا بحالــه ســكر هكــذا أجــاب‬\n      ‫هــذا كمــا جــرى االطــاع علــى لفــه رقــم (‪ )5‬وهــو تقريــر أولــي ونــص‬\n\n\n‫‪267‬‬\n\f‫احلاجــة منــه (حضــرت ســيارة مــن نــوع بســرعه جنونيــه ممــا أدى الــى‬\n‫ارتطامــه بســيارة الدوريــة فاصطــدم بالســيارة الواقفــة وارتكــب الفــرار‬\n‫أربعــة أشــخاص وضبــط ثالثــة ) اه ـ وبعــرض ذلــك علــى املدعــى عليــه‬\n‫قــال ال اعلــم حيــث أننــي كنــت يف وقتهــا ســكران هكــذا قــرر هــذا‬\n‫كمــا جــرى االطــاع علــى ملــف محاضــر لفــه رقــم(‪ )1‬وصحيفــه (‪)11‬‬\n‫ونــص احلاجــة منهــا (أنــا ‪..........‬وعنــد االصطــدام هــرب ‪.....‬وعــاد للموقــع‬\n‫)اه ـ وبعــرض ذلــك علــى املدعــى عليــه قــال ميكــن ذلــك هكــذا قــرر‬\n‫وباالطــاع علــى املعاملــة لــم أجــد فيهــا حتليــل باملــادة التــي يف القــارورة‬\n‫وبنــا علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــه املدعــى عليــه علــى‬\n‫شــرب املســكر وصــدم ســيارة دوريــات األمــن وكذلــك قيادتــه للســيارة‬\n‫حتــت تأثيــر املســكر وال عــذر ملــن اقــر ومــا تضمنــه التقريــر األولــي‬\n‫وكذلــك مــا تضمنــه احملضــر واملــدون انفــا وقــد قــال اهلل عــز وجــل‬\n‫«يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون» ‪ ،‬ويف احلديــث عــن ابــن عمر‬\n‫رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه وســلم قــال‪« :‬لعــن اهلل اخلمــر‬\n‫وشــاربها وســاقيها ومبتاعهــا وبائعهــا وعاصرهــا ومعتصرهــا وحاملهــا‬\n‫واحملمولــة إليــه» أخرجــه أبــو داود‪ ،‬وعــن ابــن عبــاس رضــي اهلل عنهمــا‬\n‫قــال‪ :‬ســمعت رســول اهلل صلــى اهلل عليــه وســلم يقــول‪« :‬أتانــي جبريــل‬\n‫فقــال يــا محمــد إن اهلل لعــن اخلمــر وعاصرهــا ومعتصرهــا وشــاربها‬\n‫واحملمولــة إليــه وبائعهــا ومبتاعهــا وســاقيها ومســقاها» أخرجــه أحمــد‬\n‫بإســناد صحيــح‪ ،‬وابــن حبــان يف صحيحــه واحلاكــم‪ ،‬وعــن عبــداهلل بــن‬\n‫عمــر رضــي اهلل عنهمــا أن الرســول صلــى اهلل عليــه وســلم قــال‪« :‬ثالثــة‬\n‫حــرم اهلل تبــارك وتعالــى اجلنــة‪ :‬مدمــن اخلمــر‪ ،‬والعــاق‪ ،‬والديــوث الــذي‬\n\n\n                                                                                       ‫‪268‬‬\n\f      ‫يقــر يف أهلــه اخلبــث»‪ ،‬وقــد انعقــد اإلجمــاع علــى أن اخلمــر حــرام شــربه‬\n      ‫واســتعماله كيفمــا كان االســتعمال‪ ،‬وذلــك ممــا علــم مــن الديــن‬\n      ‫بالضــرورة‪ ،‬وعــن جابــر بــن عبــداهلل أن رســول اهلل صلــى اهلل عليــه‬\n      ‫وســلم قــال‪« :‬كل مســكر خمــر‪ ،‬إن اهلل عهــد ملــن يشــرب املســكر‬\n      ‫أن يســقيه مــن طينــة اخلبــال‪ ،‬قالــوا يــا رســول اهلل مــا طينــة اخلبــال؟ قــال‪:‬‬\n      ‫عــرق أهــل النــار» أخرجــه مســلم يف صحيحــه وقــد ذكــر ابــن القيــم‬\n      ‫رحمــه اهلل تعالــى يف كتابــه زاد املعــاد ‪ 42/5‬مــا نصــه‪« :‬ويف مصنــف‬\n      ‫عبدالــرزاق أنــه صلــى اهلل عليــه وســلم جلــد يف اخلمــر ثمانــن» أ‪.‬هــ‪ .‬وقــد‬\n      ‫ذكــر املــرداوي يف كتابــه اإلنصــاف ‪ 422-421/26‬مــا نصــه‪« :‬ومــن‬\n      ‫شــربه مختــارا عاملــا أن كثيــره يســكر قليــا كان أو كثيــرا فعليــه‬\n      ‫احلــد ثمانــون جلــدة وهــذا املذهــب وعليــه جماهيــر األصحــاب‪ ،‬وجــزم بــه‬\n      ‫اخلرقــي وابــن عقيــل» أ‪.‬هــ‪ .‬وكذلــك إقــراره بانــه ميكــن انــه قــد هــرب‬\n      ‫ألنــه يف حالــه ســكر وقــد قــرر العلمــاء رحمهــم اهلل تعالــى بــان التعزيــر‬\n      ‫يدخــل يف احلــد لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪..........‬بشــرب‬\n      ‫املســكر وحيازتــه بربــع قــارورة مــاء صحــه بداخلهــا وقيادتــه الســيارة‬\n      ‫حتــت تأثيــر املســكر واالعتــداء علــى مركبــه رســميه ومحاولــة الهــرب‬\n                                             ‫جلميــع ذلــك فقــد حكمــت باآلتــي أوال‪:‬‬\n             ‫بجلد املدعى عليه ‪.....‬ثمانني جلده دفعه واحده وهو حد املسكر‬\n      ‫ثانيــا‪ :‬صرفــت النظــر عمــا طلبــه املدعــي العــام مــن تعزيــره علــى الكميه‬\n                                  ‫التــي معــه وذلــك لقلتهــا ولعــدم توفــر ســبب موجبه‬\n      ‫ثالثــا ‪ :‬أفهمــت املدعــى عليــه ‪.....‬بــان عقابــه علــى قيادتــه الســيارة حتــت‬\n                                                            ‫تأثيــر املســكر لولــي األمــر‬\n      ‫رابعــا‪ :‬ســجن املدعــي عليــه ‪.....‬ملــده ســته اشــهر لقــاء اصطدامــه بســيارة‬\n\n\n‫‪269‬‬\n\f‫الدوريــة ومحاولــة الهــرب اعتبــارا مــن تاريــخ اإليقــاف ‪1434/06/15‬ه ـ‬\n‫وبجلــده مائــه جلــده علــى دفعتــن كل دفعــه خمســن جلــده بــن كل‬\n‫مــره واألخــرى ســبعه أيــام خامســا ‪ :‬أمــا بالنســبة للمدعــى عليــه الثانــي‬\n‫‪.....‬فتبقــى قضيتــه وتفــرز لــه أوراق مســتقله الن املدعــى عليــه األول‬\n‫ســجني وبعرضــه علــى املدعــى عليــه قــرر قناعتــه باحلكــم أمــا املدعــى‬\n‫العــام قــرر االعتــراض واكتفــى بالئحــة االدعــاء عــن الئحــة االعتــراض‬\n                                 ‫هكــذا قــرر حــرر بتاريــخ ‪1434/07/09‬ه ــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة األولــى‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن رئيــس‬\n‫احملكمة اجلزائية بالرياض برقم ‪ 341613287‬وتاريخ ‪1434/7/16‬هـ‬\n‫واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة الشــيخ ‪.....‬‬\n‫برقــم ‪34263461‬وتاريــخ ‪1434/7/9‬ه ـ واخلــاص بدعــوى املدعــي العــام‬\n‫ضــد ‪ .....‬وموضوعهــا مســكر وانتهــاء الدراســة والتدقيــق باملصادقــة‬\n‫علــى احلكــم لعــدم موجــب املالحظــة ‪ ،‬مــع تنبيــه فضيلتــه إلــى التنويــه‬\n‫بحــق املدعــى عليه‪.....‬إلــى أنــه ســتجري محاكمتــه حــال إحضــاره واهلل‬\n                               ‫املوفــق ‪ .‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n                                                                                      ‫‪270‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":263,"source_page_end":270,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"56230debe261941278899a362da1f1bd0bd252e4c55223fa1ce32f4f778f3c72","normalized_text_hash":"7d72b7126cefe4dd5b439e2e121f9a11c5118806f441a6213fe17102cbe2db29","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p263-34263461"},{"id":"c34ab190-9ff0-5f5e-ab7d-df9c75c5d5f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -سرقة سيارة -إنكار السرقة -انطباق بصمات -تعزير للشبهة -التعزير بالسجن واجللد -إقامة حد املسكر .","document_number":"34271212","case_number":"34325002","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية الرابعة يف محكمة الاستئناف مبنطقة مكة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"مسكر -شرب املسكر -سرقة سيارة -إنكار السرقة -انطباق بصمات -تعزير للشبهة -التعزير بالسجن واجللد -إقامة حد املسكر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34271212:‬تاريخه‪1434/7/17:‬هـ‬\n                         ‫رقم الدعوى‪34325002:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34322777:‬تاريخه‪1434/09/20:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬ســرقة ســيارة ‪ -‬إنكار الســرقة ‪ -‬انطباق بصمات‬\n           ‫‪ -‬تعزير للشــبهة ‪ -‬التعزير بالســجن واجللد ‪ -‬إقامة حد املســكر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ( يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ‪.‬‬\n                     ‫‪ -2‬وقوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n       ‫‪ -3‬وقوله صلى اهلل عليه وسلم ( كل مسكر خمر وكل خمر حرام )‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                                    ‫ومالــه وعرضــه ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وســرقة‬\n      ‫ســيارة‪،‬وطلب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر‬\n      ‫وتعزيــره لقــاء ســرقة الســيارة وتشــديد العقوبــة لتعــدد ســوابقه ‪،‬حيــث‬\n      ‫قبــض علــى املدعــى عليــه إثــر بــاغ أحــد األشــخاص املتضمــن بأنه أوقف‬\n      ‫ســيارته وهــي مفتوحــة األبــواب وعليــه املفتــاح وعنــد عودتــه لــم يجدهــا‬\n      ‫وأبلــغ عــن ســرقتها وبعدهــا بســاعات عثــر عليهــا وســلمت لــه وجــرى‬\n      ‫رفــع آثــار البصمــات مــن الســيارة ومبضاهاتهــا مــن قبــل األدلــة اجلنائيــة‬\n\n‫‪271‬‬\n\f‫انطبقــت علــى بصمــات املدعــى عليــه ومت القبــض عليــه ‪،‬وباستشــمامه‬\n‫اتضــح انبعــاث رائحــة املســكر مــن فيــه ‪،‬وصــادق املدعــى عليــه علــى‬\n‫الدعــوى مــا عــدا ســرقة الســيارة فأنكرهــا ‪،‬وكانــت بينــة املدعــي‬\n‫العــام خطــاب األدلــة اجلنائيــة املتضمــن تطابــق بصمــات املدعــى عليــه‬\n‫املوجــودة داخــل الســيارة علــى البصمــات املرفوعــة مــن الســيارة ‪،‬وبنــاء‬\n‫علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه بحــد املســكر‬\n‫بجلــده ثمانــن جلــدة دفعــة واحــدة علن ـ ًا أمــام مــأ مــن النــاس ‪،‬وعــدم‬\n‫ثبــوت إدانــة املدعــى عليــه بســرقة الســيارة إال أن الشــبهة تتجــه النطبــاق‬\n‫بصماتــه وتعــدد الســوابق ‪،‬وتعزيــره بالســجن مــدة شــهرين وجلــده ثالثني‬\n‫جلــدة مكــررة عليــه مرتــن ‪،‬وقنــع املدعــى عليــه واعتــرض املدعــي العام‬\n‫‪،‬وصــدق احلكــم‬‫لكنــه لــم يقــدم الالئحــة فســقط حقــه يف االعتــراض ُ‬\n                                                 ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪ 34325002‬وتاريــخ‬\n‫‪ 1434/07/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341681212‬وتاريــخ‬\n‫‪ 1434/07/11‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/07/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 30‬لســماع دعــوى املدعــي العــام ضــد ‪ .....‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ .....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n‫‪ .....‬واملكلــف مــن قبــل هيئــة التحقيــق واالدعــاء العام مبباشــرة الدعاوى‬\n‫بهــذه احملكمــة مبوجــب كتابهــم رقــم ‪.....‬وتاريــخ ‪1433/03/06‬ه ـ‬\n\n                                                                                    ‫‪272‬‬\n\f      ‫نيابــة عــن املدعــى العــام ‪.....‬بفــرع هيئــة التحقيــق مبحافظــة جــدة‬\n      ‫وادعــى علــى ‪ 28 .....‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الهويــة رقــم‬\n      ‫(‪ ).....‬قائــا يف الئحتــه إنــه أنــه بتاريــخ ‪ 1434/6/6‬ه ـ قبــض عليــه‬\n      ‫بنــاء علــى البــاغ املقــدم بتاريــخ ‪ 1434/4/28‬ه ـ مــن املدعــي ‪ .....‬مينــي‬\n      ‫اجلنســية‪،‬املتضمن أنــه أوقــف ســيارته مــن نــوع كيــا رقــم لوحتهــا (‪).....‬‬\n      ‫وهــي مفتوحــة األبــواب وعليهــا املفتــاح وعنــد عودتــه لــم يجدهــا وأبلــغ‬\n      ‫عــن ســرقتها وبعدهــا بســاعات عثــر عليهــا وســلمت لــه ‪ ،‬وجــرى رفع آثار‬\n      ‫البصمــات مــن الســيارة ومبضاهاتهــا مــن قبــل األدلــة اجلنائيــة انطبقــت‬\n      ‫علــى بصمــات املدعــى عليــه وبإجــراء البحــث والتحريــات قبــض علــى‬\n      ‫املدعــى عليــه وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن فيــه‬\n      ‫وباســتجوابه اعتــرف بشــرب العــرق املســكر وقــد أســفر التحقيــق عــن‬\n      ‫توجيــه االتهــام إلــى املدعــى عليــه ‪ ..... /‬بشــرب املســكر وســرقة ســيارة‬\n                                          ‫املدعــي ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                                   ‫‪ -1‬ما جاء يف أقواله املدونة لفة (‪ )25‬ص( ‪)4-2‬‬\n      ‫‪ -2‬مــا جــاء يف محضــر الضبــط اجلنائــي املنــوه عنــه املرفــق بــاألوراق لفــه‬\n                                                                          ‫(‪ )23‬ص(‪)3-2‬‬\n      ‫‪ -4‬مــا جــاء يف خطــاب األدلــة اجلنائيــة بشــأن انطبــاق بصماتــه لفــة (‪)19‬‬\n      ‫‪ -5‬محضــر االستشــمام لفــة (‪ )23‬ص(‪ )4‬وبالبحــث عــن ســوابقه عثــر‬\n      ‫لــه علــى خمــس ســوابق مســجلة هــي‪1 :‬و‪ /2‬عقــوق والديــن ‪3 ،‬و‪/4‬شــرب‬\n      ‫املســكر ‪/5 ،‬شــرب املســكر وحيازتــه ‪ ،‬وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب‬\n      ‫عليــه شــرع ًا اطلــب إثبــات مــا أسن ــد إليــه واحلكــم عليــه بحــد شــرب‬\n      ‫املســكر وتعزيــره لقــاء ســرقة ســيارة املدعــي وتشــديد العقوبــة عليــه‬\n\n\n‫‪273‬‬\n\f‫لتعــدد ســوابقه التــي لــم يرتــدع بعقوباتهــا علمــا بــأن احلــق اخلــاص انتهــى‬\n‫بالتنــازل هــذه دعــواي وبتــاوة الئحــة املدعــي العــام علــى املدعــى عليــه‬\n‫ا فقد‬  ‫ا كل مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيـ ً‬       ‫أجــاب قائـ ً‬\n‫قبــض علـ ّـي مــن قبــل الدوريــات األمنيــة بتاريــخ ‪1434/6 /6‬ه ـ لقيامــي‬\n‫بشــرب املســكر حتــى ســكرت وقــد أقدمــت علــى شــرب املســكر وأنــا‬\n‫ـرعا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى‬\n                                                   ‫مســلم وأعلــم أنــه محــرم شـ ً‬\n‫هــذا الفعــل أمــا مــا ذكــره املدعــي العــام مــن قيامــي بســرقة الســيارة‬\n‫فغيــر صحيــح هكــذا أجــاب وبســؤال املدعــي العــام عــن بينتــه علــى أن‬\n‫ا بينتــي مــا جــاء يف‬‫املدعــى عليــه ‪ .....‬قــام بســرقة الســيارة أجــاب قائ ـ ً‬\n‫أوراق املعاملــة مــن أدلــه وقرائــن هكــذا أجــاب هــذا وقــد جــرى اطالعــي‬\n‫علــى أوراق املعاملــة وعلــى صحيفــة ســوابق املدعــى عليــه املرفقــة‬\n‫باملعاملــة باللفــة رقــم (‪ )16-15-14‬املتضمنــة وجــود عــدد خمــس ســوابق‬\n‫مســجلة علــى املدعــى عليــه كمــا جــرى اطالعــي علــى أقــوال املدعــى‬\n‫عليــه املرفقــة باملعاملــة لفــة رقــم (‪ )25‬صحيفــة رقــم (‪ )4-3-2‬واملتضمــن‬\n‫إقــراره بشــرب املســكر وإنــكاره ســرقة الســيارة كمــا جــرى اطالعــي‬\n‫علــى محاضــر الضبــط اجلنائــي ومحضــر االستشــمام املرفــق باملعاملــة‬\n‫لفــه (‪ )23‬صحيفــة رقــم (‪ )4-3-2‬كمــا جــرى اطالعــي علــى خطــاب‬\n‫األدلــة اجلنائيــة بشــأن انطبــاق بصمــات املدعــى عليــه املوجــودة داخــل‬\n‫الســيارة علــى البصمــات املرفوعــة مــن الســيارة لفــة (‪ )19‬فوجــدت‬\n‫اجلميــع طبــق مــا ذكــره املدعــي العــام فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة ومــا قــرره الطرفــان وإلقــراره بشــرب املســكر ألنــه ال عــذر‬\n‫ملــن أقــر علــى نفســه وإنــكاره ســرقة الســيارة لــذا فقــد ثبــت لــدي إدانــة‬\n‫املدعــى عليــه املذكــور بعاليــه مبــا نســب إليــه يف الدعــوى مــن شــربه‬\n\n\n                                                                                       ‫‪274‬‬\n\f      ‫للمســكر كمــا لــم يثبــت لــدي إدانــة املدعــى عليــه مــن قيامــه بســرقة‬\n      ‫ســيارة املدعــي إال أن الشــبهة تتجــه نحــوه بفعــل ذلــك للقرائــن التاليــة‪:‬‬\n      ‫أوالً‪ :‬انطبــاق بصماتــه كمــا هــو مســجل يف خطــاب األدلــة اجلنائيــة‬\n      ‫ثاني ـاً‪ :‬كــون املدعــى عليــه مــن أربــاب الســوابق ومبــا أن مــا قــام بــه‬\n      ‫املدعــى عليــه فعــل محــرم يســتحق العقــاب عليــه واهلل تعالــى يقــول‪( :‬‬\n      ‫يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n      ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) واهلل تعالــى يقــول ( وال‬\n      ‫تعتــدوا) ولقولــه صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل‬\n      ‫خمــر حــرام) ولقولــه صلــى اهلل عليــه وســلم‪( :‬كل املســلم علــى املســلم‬\n      ‫حــرام دمــه ومالــه وعرضــه) فلمــا ســبق فقــد حكمــت علــى املدعــى‬\n                                                            ‫عليــه لقــاء ذلــك مبــا يلــي‪:‬‬\n      ‫أوالً‪ :‬إقامــة حــد املســكر عليــه وذلــك بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n                                      ‫أ مــن النــاس لقــاء شــربه للمســكر‬       ‫أمــام مـ ً‬\n      ‫ثانيــا‪ :‬يســجن املدعــى عليــه ملــدة شــهرين يحتســب منهــا مــا أمضــاه‬\n      ‫موقوفــا يف هــذه القضيــة ويجلــد ثالثــن مكــررة عليــه مرتــن بــن كل‬\n      ‫مــرة وأخــرى مــدة ال تقــل عــن خمســة عشــر يومــا ويكــون بــن هــذا اجللــد‬\n      ‫وجلــد احلــد مــدة ال تقــل عــن خمســة عشــر يومــا وذلــك لقــاء مــا نســب‬\n      ‫إليــه مــن الشــبهة لســرقة الســيارة وبعــرض احلكــم علــى الطرفــن قــرر‬\n      ‫املدعــي العــام معارضتــه علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه‬\n      ‫فأفهمتــه باحلضــور يف يــوم األربعــاء املوافــق‪1434/07 /19‬ه ـ الســاعة‬\n      ‫احلاديــة عشــر الســتالم نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه‬\n      ‫خــال مــدة ثالثــن يومــا اعتبــار ًا مــن التاريــخ املشــار إليه فــان مضت املدة‬\n      ‫ولــم يســتلم نســخة مــن احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان‬\n\n\n‫‪275‬‬\n\f‫حقــه يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا كمــا قــرر املدعــى‬\n‫عليــه قناعتــه بــه وجــرى النطــق باحلكــم يف يــوم االثنــن املوافــق‪/17‬‬\n‫‪1434 /07‬ه ـ الســاعة ‪ 10 : 00‬وبــه أقفلــت اجللســة وعلــى ذلــك جــرى‬\n‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف‬\n                                                         ‫‪1434/07/17‬هـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ :‬نحــن رئيس وقضاة‬\n‫الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34271212‬وتاريــخ‬\n‫‪1434/7/17‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ .....‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبحافظــة جــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪،.....‬‬\n‫املتهــم يف قضيــة شــرب املســكر وســرقة ســيارة ‪ ،‬احملكــوم فيــه مبــا‬\n‫دون باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                       ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪276‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":271,"source_page_end":276,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d8d9a82157b7790a5ca01a1c001362934da636ba19a52aceac207a4bed0ffa79","normalized_text_hash":"3ba9d6a2e5b91a0e83778268fab024b2cb5bd6f346141cd47c6158d8cb7f2771","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p271-34271212"},{"id":"d51b4498-0b1b-5364-a39e-10a598016177","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -حد املسكر -نظر المحكمة يف وقائع غير مدعى بها ( القفز على منزل ) - انتهاك حرمة منزل -التعزير بالسجن واجللد .","document_number":"34332938","case_number":"34353523","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/18","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -حد املسكر -نظر المحكمة يف وقائع غير مدعى بها ( القفز على منزل ) - انتهاك حرمة منزل -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34332938:‬تاريخه‪1434/10/18:‬هـ‬\n         ‫رقم الدعوى‪ 34353523:‬رقم قرار التصديق‬\n            ‫من محكمة االستئناف‪/3439043:‬ج‪2/‬‬\n                          ‫تاريخه‪1434/12/29:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬حــد املســكر‬\n      ‫‪ -‬نظــر احملكمــة يف وقائــع غيــر مدعــى بهــا ( القفــز علــى منــزل ) ‪-‬‬\n                        ‫انتهــاك حرمــة منــزل ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n      ‫املــادة السادســة مــن نظــام اإلجــراءات اجلزائيــة ونصهــا ( وللمحكمــة أن‬\n      ‫تنظــر يف وقائــع غيــر مدعــى بهــا مــن املدعــي العــام ممــا ال يحتــاج إلــى‬\n                                                                            ‫حتقيــق ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وقيــادة‬\n      ‫الســيارة حتــت تأثيــره وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n      ‫املســكر وإفهامــه بــأن عقوبتــه عائــدة للجهــة املختصــة لقــاء قيادتــه‬\n      ‫الســيارة حتــت تأثيــر املســكر ‪،‬حيــث قبــض علــى املدعــى عليــه مــن‬\n      ‫قبــل الدوريــات األمنيــة إثــر بــاغ مــن صاحــب منــزل بقيــام املدعــى عليــه‬\n      ‫بالقفــز علــى منزلــه وباالنتقــال للموقــع شــوهد املدعــى عليــه ولوحــظ‬\n      ‫بأنــه يف حالــة غيــر طبيعيــة وباستشــمامه اتضــح انبعــاث رائحــة املســكر‬\n      ‫مــن جوفه‪،‬صــادق املدعــى عليــه علــى الدعــوى وأضــاف أنــه قــام بالقفــز‬\n      ‫مبنــزل أحــد املواطنــن ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــده‬\n\n‫‪277‬‬\n\f‫حــد املســكر ثمانــن جلــدة دفعــة واحــدة علن ـ ًا ‪ -‬إثبــات إدانتــه بالقفــز‬\n‫علــى منــزل أحــد املواطنــن وتعزيــره بالســجن ملــدة شــهر وجلــده خمســن‬\n‫جلــدة دفعــة واحــدة وإثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر‬\n‫وإفهامــه بــأن عقوبتــه عائــدة للجهــة لولــي األمــر ‪،‬قنــع املدعــى عليــه‬\n‫‪،‬وصــدق احلكــم مــن محكمــة‬        ‫واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                                    ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة علــى مــن ال نبــي بعــده وبعــد فلــدي أنــا ‪.....‬‬\n‫القاضــي باحملكمــة اجلزائيــة باألحســاء وبنــاء علــى املعاملــة الــواردة إلينا‬\n‫مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم ‪11511‬‬\n‫وتاريــخ ‪1434/07/29‬ه ـ واملقيــدة باحملكمــة برقــم ‪341837915‬‬\n‫وتاريــخ ‪1434/07/30‬ه ـ واحملالــة لــي برقــم ‪ 34353523‬وتاريــخ‬\n‫‪1434/07/30‬ه ـ افتتحــت اجللســة يف يــوم األحــد ‪1434/10/18‬ه ـ‬\n‫يف متــام الســاعة التاســعة والنصــف وفيهــا حضــر املدعــي العــام ‪.....‬‬\n‫املعمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n‫رئيــس دائــرة االدعــاء العــام مبحافظــة األحســاء ذي الرقــم ‪.....‬والتاريــخ‬\n‫‪1434/09/01‬هـ وقال يف دعواه بصفتي مدعي ًا عام ًا يف دائرة االدعاء‬\n‫العــام مبحافظــة األحســاء أدعــي علــى ‪ 25 ،.....:‬عام ـ ًا ‪ ،‬املهنــة أعمــال‬\n‫حــرة ‪ ،‬مســلم الديانــة « ســعودي اجلنســية» مبوجــب الســجل املدنــي رقــم‬\n‫( ‪ ).....‬أوقــف بتاريــخ ‪1434/3/9‬ه ـ ‪ ،‬وأفــرج عنــه بالكفالــة بتاريــخ‬\n‫‪1434/3/10‬ه ـ يقيــم يف محافظــة األحســاء ‪ ،‬حــي ‪.....‬حيــث إنــه بتاريــخ‬\n‫‪1434/3/9‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل رجــال الدوريــات‬\n\n                                                                                     ‫‪278‬‬\n\f      ‫األمنيــة مبحافظــة األحســاء إثــر بــاغ مــن املدعــو ‪ ..... /‬مفــاده قيــام‬\n      ‫املدعــى عليــه بالقفــز علــى منزلــه الواقــع بحــي ‪ (.....‬انتهــى احلــق اخلــاص‬\n      ‫بالتنــازل ) ‪ ،‬وباالنتقــال للموقــع شــوهد املدعــى عليــه ولوحــظ بأنــه‬\n      ‫يف حالــة غيــر طبيعيــة ( ســكر ) وباستشــمامه اتضــح انبعــاث رائحــة‬\n                                                                    ‫املســكر مــن جوفــه ‪.‬‬\n      ‫وبضبــط إفــادة املبلــغ ‪..... /‬أفــاد مبشــاهدته للمدعــى عليــه فــوق ســور‬\n                                                                 ‫اجلــدار األمامــي ملنزلــه ‪.‬‬\n      ‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وشــربه‬\n                 ‫للمســكر ‪ ،‬وقيــادة الســيارة حتــت تأثيــر شــرب املســكر ‪.‬‬\n      ‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بشــرب املســكر ‪ ،‬وقيــادة‬\n      ‫الســيارة حتــت تأثيــره ؛ وذلــك لألدلــة والقرائــن التاليــة ‪ .1 :‬إقــراره املدون‬\n                     ‫علــى الصفحــة رقــم ( ‪ ) 14‬مــن ملــف التحقيــق لفــة رقــم ( ‪) 1‬‬\n      ‫‪ .2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم ( ‪ ) 6‬مــن ملــف‬\n                                                              ‫التحقيــق لفــة رقــم ( ‪. ) 1‬‬\n                                       ‫‪ .3‬محضر القبض املرفق على لفة رقم ( ‪. ) 2‬‬\n      ‫‪ .4‬أقــوال املبلــغ املدونــة علــى الصفحــة رقــم ( ‪ ) 10 ، 9‬مــن ملــف التحقيق‬\n                                                                             ‫لفــة رقــم ( ‪. ) 1‬‬\n      ‫وبالبحــث عمـ ــا إذا كـ ــان لــه سـ ــوابق عثــر ل ــه علــى ســابقة اســتعمال‬\n                                                                    ‫املخــدرات وحيازتــه ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا ؛ أطلــب إثبــات مــا‬\n                                               ‫أســند إليــه ‪ ،‬واحلكــم عليــه باآلتــي ‪:‬‬\n                                                ‫‪ .1‬بعقوبة حد السكر لقاء شربه له ‪.‬‬\n\n\n‫‪279‬‬\n\f‫‪ .2‬إثبــات قيادتــه للســيارة وهــو حتــت تأثيــر شــرب املســكر ‪ ،‬وإفهامــه‬\n‫بــأن عقابــه علــى ذلــك عائــد للجهــة املختصــة اســتنا ًدا للفقــرة ( أو ًال ) مــن‬\n                                                    ‫املــادة ( ‪ ) 68‬مــن نظــام املــرور ‪.‬‬\n‫هــذه دعــواي عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه‬\n‫ا ‪ :‬مــا ذكــره‬      ‫جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائ ـ ً‬\n‫املدعــي العــام مــن شــربي للمســكر وقيادتــي للســيارة حتــت تأثيرهــا‬\n‫فصحيــح وذلــك أننــي شــربت املســكر وقمــت بالقفــز علــى منــزل أحــد‬\n‫املواطنــن ولــم أكــن أي غــرض ســيء وأنــا تائــب ونــادم علــى مــا بــدر‬\n‫منــي وصحيــح نســبة الســابقة لــي وقــد أخــذت محكوميتهــا هكــذا‬\n‫أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪ :‬كــرت‬\n‫ـاء‬\n  ‫ســوابق علــى املدعــى عليــه املتضمــن وجــود ســابقة مخــدرات عليــه فبنـ ً‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة بعــد النظــر يف حــال املدعــى عليــه‬\n‫أن‬   ‫والتأكــد مــن أهليتــه وبعــد دراســة أرواق املعاملــة وتأملهــا ومبــا َّ‬\n‫املدعــى عليــه أقـ َّـر بقيــام بالقفــز علــى منــزل أحــد املواطنــن وبنــاء علــى‬\n‫املــادة السادســة مــن نظــام اإلجــراءات اجلزائيــة ونصهــا ‪ « :‬وللمحكمــة‬\n‫تنظــر يف وقائــع غيــر ُمدعــى ِبهــا مــن املُدعــي العــام ِّمــا ال يحتــاج‬    ‫أن ُ‬\n‫أن املدعــى عليــه أقـ َّـر بشــرب املســكر مختــار ًا عاملـ ًا‬  ‫إلــى حتقيــق» ومبــا َّ‬\n‫ـتقر‬\n   ‫بتحرميــه وحـ ُّـد املســكر أن يجلــد صاحبــه ثمانــن جلــدة كمــا اسـ َّ‬\n‫أن املدعــى عليــه‬    ‫ممــا يتوجــب حــد املدعــى عليــه ومبــا َّ‬ ‫عليــه عمــل األمــة َّ‬\n‫أقـ َّـر بقيــادة الســيارة حتــت تأثيــر املســكر وإثبــات قيادتــه حتــت تأثيرهــا‬\n‫لــدى هــذه احملكمــة والعقوبــة لــدى ولــي األمــر حســب األنظمــة املرعيــة‬\n‫التــي ال تتعــارض مــع املصالــح الشــرعية لــذا كلــه وألجــل احلــق العــام‬\n‫حكمــت علــى املدعــى عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لــدي إدانــة املدعــى‬\n\n\n                                                                                             ‫‪280‬‬\n\f      ‫عليــه بشــرب املســكر مختــارا عاملــا بتحرميــه و يجلــد حــد املســكر‬\n                                                     ‫ثمانــن جلــدة دفعــة واحــدة علنـ ـ ًا ‪.‬‬\n      ‫ثانيـ ًا ‪ /‬ثبــت لــدي إدانــة املدعــى عليــه بالقفــز علــى منــزل أحــد املواطنــن‬\n      ‫وعزرتــه لقــاء ذلــك بســجنه ملــدة شــهر حتتســب منهــا املــدة التــي أوقــف‬\n      ‫فيهــا علــى ذمــة القضيــة وبجلــده خمســون جلــدة دفعــة واحــدة بينــه وبــن‬\n              ‫احلــد مــدة ال تقــل عــن عشــرة أيــام ويكــون جلــد احلــد هــو املقــدم ‪.‬‬\n      ‫ـدي إدانــة املدعى عليه بقيادة الســيارة حتت تأثير املســكر‬             ‫ثالثـاً‪ /‬ثبــت لـ َّ‬\n      ‫ـأن عقوبتــه عائــدة لولــي األمــر وبتــاوة احلكــم علــى الطرفــن‬         ‫وأفهمتــه بـ َّ‬\n      ‫وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر قناعتــه باحلكم وطلب‬\n      ‫املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم دون الئحــة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى‬\n      ‫هــذا وقــد جــرى توجيــه املدعــى عليــه مبــا يلــزم ومــن ذلــك حرمــة اخلمــر‬\n      ‫وأثرهــا الســيئ عليــه وعلــى املجتمــع وأقفلــت اجللســة الســاعة العاشــرة‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم وصــدر‬\n                                                         ‫احلكــم يف ‪1434/10 /18‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/2478034‬ج‪ 2‬وتاريــخ ‪1434/11/02‬ه ـ‬\n      ‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة األحســاء املكلــف‬\n      ‫برقــم ‪ 341837915‬وتاريــخ ‪1434/10/25‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬املســجل برقــم‬\n      ‫‪ 34332938‬وتاريــخ ‪1434/10/18‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n      ‫ضــد ‪...../‬يف قضيــة مســكر وقيــادة الســيارة حتــت تأثيرهــا وقــد‬\n\n\n‫‪281‬‬\n\f‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                          ‫‪1434/12/25‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪282‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":277,"source_page_end":282,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"37f8ce0338b2797c28c471895e1223a844e96a688c8811a97ae42d6181c49870","normalized_text_hash":"17909aa8f92515dc9ee9aa340a1f69acc1f946c69d47656b74c1618f28857306","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p277-34332938"},{"id":"1f807321-df56-5190-b548-772960ad39a1","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -محاولة دهس شخص -تنازل صاحب احلق اخلاص -إقراره حتقيق ا -رجوع عن اإلقرار بعد احلكم -قبول رجوع املقر عن إقراره -درء احلدود بالشبهات -التعزير بالسجن","document_number":"34332196","case_number":"34439386","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/18","year":"1434","subject":"مسكر -شرب املسكر -محاولة دهس شخص -تنازل صاحب احلق اخلاص -إقراره حتقيق ا -رجوع عن اإلقرار بعد احلكم -قبول رجوع املقر عن إقراره -درء احلدود بالشبهات -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34332196:‬تاريخه‪1434/10/18:‬هـ‬\n                   ‫رقم الدعوى‪34439386:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34352540:‬تاريخه‪1434/11/06:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬محاولــة دهــس شــخص ‪ -‬تنــازل صاحــب احلــق‬\n‫اخلــاص ‪ -‬إقــراره حتقيق ـ ًا ‪ -‬رجــوع عــن اإلقــرار بعــد احلكــم ‪ -‬قبــول‬\n‫رجــوع املقــر عــن إقــراره ‪ -‬درء احلــدود بالشــبهات ‪ -‬التعزيــر بالســجن‬\n                                                                    ‫واجللــد ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( إن دمائكــم وأموالكــم وأعراضكــم‬\n                                                              ‫عليكــم حــرام) ‪.‬‬\n‫‪ -2‬قــول ابــن قدامــة يف املغنــي ‪ (162/9‬وإذا رجــع عــن إقــراره قبــل رجوعــه‬\n           ‫ألنــه حــد هلل ســبحانه فقبــل رجوعــه عنــه كســائر احلــدود ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بشــرب املســكر ومبحاولــة‬\n‫األول دهــس املدعــى عليــه الثانــي وإصابتــه وطلــب إثبــات مــا أســند‬\n‫إليهمــا واحلكــم عليهمــا بحــد املســكر وعقوبــة تعزيريــة مشــددة علــى‬\n‫األول لشــناعة جرمــه حيــث تقــدم املدعــى عليــه الثانــي بشــكوى علــى‬\n‫األول املتضمنــة بأنــه حــاول صدمــه حيــث حضــر املدعــى عليــه األول‬\n‫إلــى الثانــي يف مقــر عملــه واصطحبــه معــه يف الســيارة واجتــه بــه إلــى‬\n‫أحــد الطــرق ثــم توقــف بعــد محطــة الوقــود للتفاهــم معــه حــول مشــكلة‬\n                                                                                   ‫‪290‬‬\n\f      ‫بينهمــا وبنــزول املدعــى عليــه الثانــي مــن الســيارة قــام املدعــى عليــه األول‬\n      ‫بالتحــرك وصــدم املدعــى عليــه الثانــي ثــاث مــرات ‪ ،‬وأثبــت التقريــر‬\n      ‫الطبــي بإصابــة املدعــى عليــه الثانــي برضــوض وجــرح تهتكــي ‪،‬وصادق‬\n      ‫املدعــى عليــه األول بشــرب املســكر وأنكــر الدهــس وأنــه رجــع‬\n      ‫بالســيارة والبــاب مفتــوح واصطــدم بــه البــاب ‪،‬كمــا أنكــر املدعــى‬\n      ‫عليــه الثانــي شــرب املســكر ‪ ،‬بينــة املدعــي العــام هــي التقريــر الطبــي‪،‬‬\n      ‫وإقــرار الطــرف الثانــي بشــرب املســكر يف محضــر املواجهة‪،‬وبنــاء‬\n      ‫علــى مــا تقــدم حكمــت احملكمــة بجلــد املدعــى عليــه األول ثمانــن‬\n      ‫جلــدة حــد املســكر وتعزيــره بســجنه شــهرين لقــاء صدمــه املدعــى عليــه‬\n      ‫الثانــي ‪،‬ورد دعــوى املدعــي العــام بإقامــة حــد املســكر علــى املدعــى‬\n      ‫عليــه الثانــي وبتعزيــره بجلــده ثالثــن جلــدة لقــاء التهمــة ‪،‬قنــع املدعــى‬\n      ‫عليــه األول واعتــرض املدعــي العــام مكتفيــا بالئحــة الدعــوى كمــا‬\n      ‫اعتــرض املدعــى عليــه الثانــي وبعــد إعــان احلكــم رجــع املدعــى عليــه‬\n      ‫األول عــن اإلقــرار بشــرب املســكر ‪،‬وملــا قــرره أهــل العلــم بقبــول رجــوع‬\n      ‫املقــر علــى نفســه باحلــد عــن إقــراره قبــل إقامــة احلــد ‪ ،‬عــدم إثبــات إدانــة‬\n      ‫املدعــى عليــه األول بشــرب املســكر واحلكــم بصــرف النظــر عــن طلــب‬\n      ‫املدعــي العــام بإقامــة حــد املســكر وتعزيــره علــى التهمــة القويــة بجلــده‬\n      ‫تســع ًا وســبعني جلــدة وقنــع املدعــى عليــه باحلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                                 ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪291‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34439386‬وتاريــخ ‪ 1434/10/07‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 342249950‬وتاريــخ ‪ 1434/09/27‬ه ـ ففــي يــوم‬\n‫األربعــاء ‪ 1434/10/14‬ه ـ فتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام ‪ .....‬مدعي ـ ًا علــى احلاضريــن معــه ‪ ..... :‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬و ‪ .....‬ســعودي اجلنســية‬\n‫ا يف دعــواه عليهــم ‪ :‬إنــه يف يــوم‬‫مبوجــب الســجل املدنــي (‪ ).....‬قائ ـ ً‬\n‫األحــد املوافــق ‪1434/9/13‬ه ـ تقــدم املواطــن (‪ ).....‬بشــكوى ملركــز‬\n‫شــرطة (‪ ).....‬ضــد املتهــم (‪ ).....‬يدعــي فيهــا بــأن (‪ ).....‬حــاول صدمــه‬\n‫وبســماع أقــوال املتهــم (‪ ).....‬ذكــر أن املتهــم (‪ ).....‬زميلــه (جنــدي أول‬\n‫ويعمــل معــه بنفــس الفرقــة) حضــر لــه مبقــر عملــه ثــم اصطحبــه بســيارة‬\n‫املتهــم (‪ ).....‬مــن نــوع لونهــا بحــري و ســنة صنعهــا (‪2006‬م) واجتــه بــه‬\n‫إلــى طريــق ثــم توقــف بعــد محطــة ‪.....‬بنصــف كيلــو تقريبــا للتفاهــم معــه‬\n‫حــول مشــكلة قدميــة وبنــزول املتهــم (‪ ).....‬قــام املتهــم (‪ ).....‬بالتحــرك‬\n‫والتفحيــط وصــدم املتهــم ‪ .....‬ثــاث مــرات وكانــا بالــزي العســكري‪.‬‬\n‫وبإعــادة ضبــط الشــكوى ذكــر املتهــم ‪ .....‬ذكــر بأنــه يف صبــاح يــوم‬\n‫األحــد املوافــق ‪1434/9/13‬ه ـ كان مبقــر عملــه (بالــزي العســكري)‬\n‫فحضــر إليــه املتهــم ‪(.....‬بالــزي العســكري) وطلــب منــه مرافقتــه‬\n‫فرفــض وأصــر عليــه بركــوب الســيارة وقــال لــه (نبــي نحــط النقــاط‬\n‫علــى احلــروف) فرفــض الركــوب و وقــف املتهــم ‪.....‬بجانــب املتهــم ‪.....‬‬\n\n                                                                                    ‫‪292‬‬\n\f      ‫وكان املتهــم (‪ ).....‬يحــاول إقناعــه بالركــوب معــه بســيارته فركــب‬\n      ‫املتهــم (‪ ).....‬وقــال املتهــم (‪ ).....‬بنــروح نصلــي باملســجد هنــاك أنظــف‬\n      ‫‪ ،‬فتوجــه إلــى طريــق طريــف ولــم يتوقــف عنــد املســجد إلــى أن وصــل‬\n      ‫هجــرة ‪.....‬ثــم عــاد إلــى ثــم رجــع وتوجــه إلــى طريــق حتــى وصــل إلــى ثــم‬\n      ‫رجــع مــرة أخــرى إلــى ثــم عــاد إلــى طريــق واجتــه إلــى طريــق فرعــي ونــزل‬\n      ‫بالســيارة مــع طريــق صحــراوي وبعــد مســافة تقــدر بثالثــة كيلــو متــرات‬\n      ‫توقــف املتهــم (‪ ).....‬وكان يريــد املفاهمــة مــع املتهــم (‪ ).....‬فنــزل املتهــم‬\n      ‫(‪ ).....‬مــن الســيارة فقــام املتهــم (‪ ).....‬بالرجــوع بســيارته وبابهــا مفتــوح‬\n      ‫فصــدم املتهــم (‪ ).....‬ثــم تقــدم املتهــم (‪ ).....‬بســيارته وصــدم املتهــم (‪).....‬‬\n      ‫مــن رجلــه مــرة أخــرى فتمســك املتهــم (‪ ).....‬مبســاحة الســيارة بيــده‬\n      ‫اليمنــى وكان املتهــم ‪.....‬علــى ســرعته وعندمــا توقــف ســقط املتهــم‬\n      ‫(‪ ).....‬ثــم حــاول املتهــم ‪.....‬صــدم املتهــم ‪.....‬مــرة أخــرى فأخــذ املتهــم ‪.....‬‬\n      ‫بيــده تــراب وحصــى وتوجــه إلــى فــوق تــل فأخــذ حجــر ثــم غــادر املتهــم‬\n      ‫‪.....‬املوقــع ‪ .‬وباســتجواب املتهــم ‪ .....‬أقــر باصطحــاب املتهــم ‪ .....‬علــى‬\n      ‫طريــق وذكــر أنــه يف يــوم األحــد املوافــق ‪1434/9/13‬ه ـ خــرج املتهم‪.....‬‬\n      ‫يرافقــه املتهــم ‪ .....‬علــى طريــق ســكاكا ثــم وصــل وعــاد إلــى وكانــوا‬\n      ‫يتناقشــون حــول موضــوع فتوقــف قبــل محطــة ‪ .....‬فنــزل املتهــم ‪.....‬‬\n      ‫وطلــب املتهــم ‪ .....‬مــن املتهــم ‪.....‬الركــوب فرفــض فتحــرك فقــام املتهــم‬\n      ‫‪.....‬برمــي املتهــم ‪.....‬بحجــر فأصابــت الزجــاج األمامــي وبضبــط شــهادة‬\n      ‫الشــاهد ‪ .....‬ذكــر أن املتهــم ‪.....‬اتصــل عليــه صبــاح يــوم األحــد املوافــق‬\n      ‫‪1434/9/13‬ه ـ وطلــب منــه احلضــور إلــى طريــق بالقــرب مــن محطــة ‪.....‬‬\n      ‫وعنــد وصــول الشــاهد إلــى نقطــة تفتيــش ‪ .....‬اتصــل علــى املتهــم ‪.....‬‬\n      ‫وســأله عــن مكانــه حتديــد ًا فقــال املتهــم ‪(.....‬بعــد مــا تتعــدى الرصيــف‬\n\n\n‫‪293‬‬\n\f‫حــق النقطــة خــذ فــوق حتــت تلقانــي واقــف على اليمــن بســيارة ‪ ).....‬فلما‬\n‫وصــل الشــاهد ركــب املتهــم ‪ .....‬بســيارة الشــاهد وذكــر لــه مــا حصــل‬\n‫‪ ،‬كمــا شــاهد وجــود دم علــى الكتــف األميــن للمتهــم ‪ .....‬و متــزق الفنيلــة‬\n‫مــن مــكان الكتــف األميــن ‪ ،‬كمــا ذكــر أن ســيارة املتهــم ‪ .....‬هــي مــن‬\n‫نــوع و لونهــا بحــري ‪.‬ومبعاينــة موقــع احلادثــة وجــدت آثــار تفحيــط و أثريــن‬\n‫علــى شــكل قــوس ‪ .‬ومبعاينــة الســيارة ( اللــون أزرق فــاحت ســنة صنعهــا‬\n‫‪ ، 2006‬حتمــل اللوحــة ‪ ).....‬تبــن وجــود أتربــة وغبــار وكدمــات خفيفــة‬\n‫مــن اجلهــة األماميــة ‪ .‬وبتفريــغ رســالة نصيــة صــادرة مــن الرقــم (‪).....‬‬\n‫إلــى رقــم املتهــم (‪ ).....‬بتاريــخ ‪/23‬يوليــو ‪ ،‬يف متــام الســاعة (‪ 3.27‬ص)‬\n‫كان نصهــا مــا يلــي ‪ :‬الســام عليكــم أو ًال احلمــد هلل علــى الســامة‬\n‫ومــا تشــوف شــر يــا رب وخطــاك الســوء يف البدايــة مقدريــن الضــرر‬\n‫اللــي حصــل ولــم نكــن نتمناهــا أبــد ًا ولكــن طمعانــن يف عفــوك أخــوي‬\n‫أبــو ‪.....‬والعفــو مــن شــيم الرجــال وأنــت رجــال مبعنــى الكلمــة مــن‬\n‫خــال مواقفــك التــي لــن ننســاها مــع أخينــا أبــو ‪.....‬فكلنــا رجــاء بــك‬\n‫أن تعفــو وتصفــح عــن أخينــا وتكــون ســبب ًا يف إصالحــه معنــا ونتعهــد‬\n‫بــأن تكــون هــذه األخيــرة أن لــم يكــن ألجلنــا فمــن أجــل ‪ .....‬و‪ .....‬فهــو‬\n‫عونهــن بعــد اهلل تعالــى وســندهن يف هــذه احليــاة ومــن أجــل الوظيفــة وال‬\n‫يخفــى عليــك صعوبــة احلصــول عليهــا يف زمننــا هــذا كلنــا أمــل يف اهلل‬\n‫تعالــى ثــم بــك لتعفــو ونفتــح صفحــة جديــدة يف حيــاة أخينــا شــاكرين‬\n‫ومقدريــن لــك أو ًال وأخيــرا‪ .‬وبإجــراء املواجهــة بــن املتهــم ‪.....‬واملتهــم ‪،.....‬‬\n‫ذكــر املتهم‪.....‬بــأن املتهــم ‪ .....‬شــرب املســكر بــاألردن فنشــب بينهمــا‬\n‫خــاف وأقــرا بشــربهما املســكر و أصــر كل منهمــا علــى قولــه يف‬\n‫محاولــة الدهــس ولــم يتبــن قــوة حجــة أحدهمــا علــى اآلخــر ولــم يالحــظ‬\n\n\n                                                                                           ‫‪294‬‬\n\f      ‫عليهمــا مــا يســتحق ذكــره وقــد صــدر تقريــر طبــي بحــق املتهــم ‪ .....‬مــن‬\n      ‫مستشــفى عرعــر املركــزي برقــم ‪.....‬وتاريــخ ‪1434/9/15‬ه ـ املتضمــن‬\n      ‫إصابتــه برضــوض بســيطة يف الكتــف األميــن مــن اخللــف وكلتــا اليديــن‬\n      ‫وتهتــك بقيــاس (‪ 5‬ســم) تقريب ـاً‪ ،‬وإصابتــه بجــرح تهتكــي يف الســاق‬\n      ‫األميــن ومــدة الشــفاء ثالثــة أيــام وقــد انتهــى التحقيــق إلــى اتهــام ‪ .....‬و‬\n      ‫‪ .....‬بشــربهما املســكر ‪ ،‬واتهــام ‪ .....‬مبحاولــة دهــس شــخص وإصابتــه‬\n      ‫باإلصابــات املوصوفــة بالتقريــر الطبــي وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬مــا ورد يف محضــر معاينــة موقــع احلادثــة املرفــق لفــة رقــم (‪-2 )29‬‬\n      ‫مــا ورد يف محضــر معاينــة الســيارة املرفــق لفــة رقــم (‪ -3 )30‬مــا ورد‬\n      ‫بالتقريــر الطبــي املرفــق لفــة رقــم (‪ -4 )15‬مــا ورد يف شــهادة الشــاهد‬\n      ‫املدونــة علــى الصفحــة رقــم (‪ )2-1‬مــن املرفــق لفــة رقــم (‪ -5 )22 -21‬مــا‬\n      ‫ورد يف محضــر تفريــغ رســالة نصيــة املرفــق لفــة رقــم (‪ -6 )17‬مــا ورد‬\n      ‫يف محضــر املواجهــة املــدون علــى الصفــح لفــة رقــم (‪ -7 )16‬مــا ورد يف‬\n      ‫أقــوال ‪.....‬املدونــة علــى الصفحــة رقــم (‪ )1‬مــن املرفــق لفــة رقــم (‪)13‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكوريــن وهمــا بكامــل أهليتهمــا املعتبــرة‬\n      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتهمــا مبــا‬\n      ‫نســب إليهمــا واحلكــم عليهمــا بحــد شــرب املســكر ‪ ،‬واحلكــم علــى‬\n      ‫املتهــم ‪ .....‬بعقوبــة تعزيريــة مشــددة لشــناعة جرمــه ‪( .‬علم ـ ًا بــأن احلــق‬\n      ‫اخلــاص انتهــى بالتنــازل) هــذه دعــواي وبعــرض الدعــوى علــى املدعــى‬\n      ‫عليهمــا أجــاب األول ‪.....‬بقولــه مــا ذكــره املدعــي العــام مــن قيامــي‬\n      ‫بشــرب املســكر صحيــح وبالنســبة مبحاولــة دهــس املدعــى عليــه ‪.....‬‬\n      ‫ثــاث مــرات فغيــر صحيــح والصحيــح أنــه كان راكبـ ًا معــي ونــزل مــن‬\n      ‫الســيارة فرجعــت بالســيارة وبابهــا مفتــوح وصــدم بــه البــاب وســقط علــى‬\n\n\n‫‪295‬‬\n\f‫األرض ثــم طلبــت منــه الركــوب معــي فرفــض ذلــك فذهبــت وتركتــه‬\n‫هكــذا أجــاب وأجــاب املدعــى عليــه الثانــي ‪.....‬بــأن مــا ذكــره املدعــي‬\n‫العــام مــن قيامــي بشــرب املســكر غيــر صحيــح إطالقـ ًا وأضــاف أيضـ ًا‬\n‫بــأن املدعــى عليــه ‪.....‬صديــق لــه وأنــه قــد تنــازل عــن حقــه اخلــاص وأنــه‬\n‫ال خــاف بينهــم هكــذا أضــاف وبســؤال املدعــي العــام عــن بينتــه فيمــا‬\n‫يدعيــه مــن قيــام املدعــى عليــه األول ‪.....‬مــن قيامــه مبحاولــة دهــس‬\n‫املدعــى عليــه ‪.....‬ثــاث مــرات فقــال بينتــي فقــال مــا جــاء يف أوراق‬\n‫املعاملــة وكذلــك مــا جــاء يف إفــادة املدعــى عليــه الثانــي ‪.....‬وكذلــك‬\n‫مــا جــاء بالتقريــر الطبــي املرفــق هكــذا أجــاب وبســؤاله أيض ـ ًا عــن‬\n‫بينتــه علــى مــا يدعيــه مــن قيــام املدعــى عليــه الثانــي ‪.....‬بشــرب املســكر‬\n‫فقــال بينتــي مــا جــاء يف محضــر املواجهــة املرفــق باملعاملــة هكــذا أجاب‬\n‫هــذا وبالرجــوع إلــى محضــر املواجهــة املرفــق باملعاملــة لفــة رقــم(‪)16‬‬\n‫ونــص احلاجــة منــه (وأقــر الطــرف األول بشــرب املســكر واتهــم الثانــي‬\n‫بشــرب املســكر وأقــر الطــرف الثانــي بشــرب املســكر) الطــرف األول‬\n‫‪.....‬توقيعــه الطــرف الثانــي ‪ .....‬توقيعــه وبالرجــوع إلــى التقريــر الطبــي‬\n‫املرفــق باملعاملــة لفــة رقــم (‪ )15‬املتضمــن إصابتــه برضــوض بســيطة‬\n‫يف الكتــف األميــن مــن اخللــف وكلتــا اليديــن وتهتــك بقيــاس (‪ 5‬ســم)‬\n‫تقريبـ ُا ‪ ،‬وإصابتــه بجــرح تهتكــي يف الســاق األميــن ومــدة الشــفاء ثالثــة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى‬\n                                  ‫أيــام مــا لــم حتــدث مضاعفــات انتهــى فبنـ ً‬\n‫واإلجابــة ومــا جــاء مبحضــر املواجهــة بــن الطرفــن وكذلــك مــا جــاء‬\n‫يف التقريــر الطبــي املذكــور وحيــث أقــر املدعــى عليــه األول ‪.....‬بقيامــه‬\n‫بالرجــوع بالســيارة علــى املدعــى عليــه الثانــي وصدمــه إيــاه بالبــاب ولــم‬\n‫يحضــر املدعــي العــام البينــة علــى مــا ذكــره مــن محاولــة دهــس املدعــى‬\n\n\n                                                                                       ‫‪296‬‬\n\f      ‫عليــه ‪.....‬للمدعــى عليــه ‪.....‬ثــاث مــرات وحيــث إن هــذا مــن االعتــداء‬\n      ‫علــى األنفــس املعصومــة بغيــر حــق ولقولــه صلــى اهلل عليــه وســلم (إن‬\n      ‫دمائكــم وأموالكــم وأعراضكــم عليكــم حــرام) متفــق عليــه مــن‬\n      ‫حديــث أبــي بكــرة وملــا جــاء مــن أن املدعــى عليهمــا بينهمــا صحبــة‬\n      ‫وعالقــة حميمــة وقــد تنــازل املدعــى عليــه ‪ .....‬عــن حقــه اخلــاص جتــاه‬\n      ‫املدعــى عليــه ‪.....‬نظــر ًا حلفــظ الــود بينهمــا وحيــث أنكــر املدعــى عليــه‬\n      ‫‪.....‬قيامــه بشــرب املســكر ومــا جــاء يف محضــر املواجهــة بينهمــا يعــد‬\n      ‫قرينــة توجــب توجــه التهمــة لــه بشــرب املســكر لــذا فلــم يثبــت لــدي‬\n      ‫إدانــة املدعــى عليــه األول مبحاولــة دهــس املدعــى عليــه الثانــي ثــاث‬\n      ‫مــرات وإمنــا ثبــت لــدي قيامــه بالرجــوع عليــه وصدمــه بالبــاب مــرة واحــدة‬\n      ‫أثنــاء نزولــه وثبــت لــدي إدانتــه بشــرب املســكر ولــم يثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه الثانــي بشــرب املســكر وإمنــا تتوجــه التهمــة لــه بذلــك‬\n      ‫وحكمــت مبــا يلــي‪ :‬أوالً‪ :‬جلــد املدعــى عليــه األول ثمانــن جلــدة حــد‬\n      ‫املســكر لقــاء شــربه للمســكر ثاني ـ ًا ‪ :‬تعزيــره وذلــك بســجنه ملــدة‬\n      ‫شــهرين وجلــده ســبعني جلــدة لقــاء قيامــه بصــدم املدعــى عليــه الثانــي‬\n      ‫ببــاب الســيارة ثالثـاً‪ :‬ردع طلــب املدعــي العــام إقامــة حــد املســكر علــى‬\n      ‫املدعــى عليــه الثانــي ‪.....‬لعــدم ثبــوت اإلدانــة واالكتفــاء بتعزيــره وذلــك‬\n      ‫بجلــدة ثالثــن جلــدة لقــاء التهمــة بذلــك وبإعــان احلكــم قنــع بــه املدعــى‬\n      ‫عليــه األول ‪.....‬ولــم يقنــع بــه املدعــي العــام وال املدعــى عليــه ‪.....‬وطلبــا‬\n      ‫االســتئناف بــا الئحــة معتبــر ًا املدعــي العــام الئحــة الدعــوى الئحــة‬\n      ‫اعتراضيــة وبعــد إعــان ذلــك قــال املدعــى عليــه ‪.....‬بأننــي لــم أشــرب‬\n      ‫املســكر أبــد ًا وإمنــا أقــررت علــى نفســي ظن ـ ًا منــي بأننــي ســأخرج مــن‬\n      ‫الســجن هكــذا قــال وبنــاء عليــه وحيــث قــرر العلمــاء بــأن مــن أقــر علــى‬\n\n\n‫‪297‬‬\n\f‫نفســه بشــرب مســكر ثــم رجــع عــن إقــراره قبــل إقامــة احلــد عليــه فــإن‬\n‫رجوعــه عــن إقــراره يقبــل ويــدرأ عنــه احلــد قــال ابــن قدامــة يف بــاب شــرب‬\n                   ‫وع ـ ُه؛ ِ َل َّن ـ ُه َحـ ٌّـد ِ َّ ِ‬\n‫ل ُس ـ ْب َحا َن ُه‪،‬‬                                   ‫(و ِإ َذا َر َجـ َـع َعــنْ ْإقـ َـرا ِر ِه قُ ِبــلَ ُر ُج ُ‬\n                                                                                                                  ‫املســكر َ‬\n‫الـ ُـدودِ‪ ) .‬املغنــي ‪ 162/9‬ونظــر ًا إلقــرار‬                         ‫ك َســائ ِِر ْ ُ‬     ‫وع ـ ُه َع ْن ـ ُه‪َ ،‬‬ ‫َف ُق ِبــلَ ُر ُج ُ‬\n‫املدعــى عليــه بشــرب املســكر يف أول اجللســة ثــم رجوعــه عــن إقــراره‬\n‫بعــد احلكــم عليــه ممــا يوجــه التهمــة القويــة لــه بشــرب املســكر لــذا لــم‬\n‫يثبــت لــدي إدانــة املدعــى عليــه ‪.....‬بشــرب املســكر وحكمــت بصــرف‬\n‫النظــر عــن طلــب املدعــي العــام إقامــة حــد املســكر علــى املدعــى عليــه‬\n‫‪.....‬وقــررت تعزيــره بنــاء علــى التهمــة القويــة وذلــك بجلــدة تســع ًا وســبعني‬\n‫جلــدة وبــه حكمــت وبإعــان احلكــم قنــع بــه املدعــى عليــه ‪.....‬وقــررت‬\n‫رفــع املعاملــة حملكمــة االســتئناف مبنطقــة اجلــوف وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                                                      ‫‪ 1434/10/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة األولــى‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعــر برقــم‬\n‫‪ 342249950‬وتاريــخ ‪1434/10/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪34332196‬‬\n‫وتاريــخ ‪1434/10/18‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد (‪).....‬‬\n‫ورفيقــه يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫فقــد قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                                     ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                                                                          ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":290,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8c3574cd4c8cbe59be8bf9c2522030f114fd05ba45c4d4e20d85db899638bddf","normalized_text_hash":"cd2e417bbbf74c3742dd0e03e8c9e7095995211ed93f29a9ae3dd383d116562b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p290-34332196"},{"id":"a21e6235-a449-58de-9847-9d41c0b012fd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -إحداث فوضى -التعزير للشبهة -درء حد املسكر -التعزير باجللد .","document_number":"3443649","case_number":"3444662","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"مسكر -شرب املسكر -إحداث فوضى -التعزير للشبهة -درء حد املسكر -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 3443649 :‬تاريخه‪1434/2/23:‬هـ‬\n                         ‫رقم الدعوى‪3444662:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34167023‬تاريخه‪1434/3/21 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬إحــداث فوضــى ‪ -‬التعزيــر للشــبهة ‪ -‬درء حــد‬\n                                                     ‫املســكر ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n      ‫‪ .1‬التعزيــر ال يســقط بالشــبهة جــاء يف األشــباه والنظائــر للســيوطي‬\n                                     ‫ص‪ ( 162‬الشــبهة ال تســقط التعزيــر ) ‪.‬‬\n      ‫‪ .2‬قــال ابــن جنيــم يف األشــباه والنظائــر ‪ ( 157‬التعزيــر يثبــت مــع‬\n      ‫الشــبهة ولــذا قالــوا يثبــت مبــا يثبــت بــه املــال ويجــري فيــه احللــف‬\n                                                      ‫ويقضــى فيــه بالنكــول ) ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وإحــداث‬\n      ‫الفوضى بإثارة املشــاكل مع أخيه‪،‬وطلب إثبات ما أســند إليه واحلكم‬\n      ‫عليــه بحــد املســكر وعقوبــة تعزيريــة لقــاء إحــداث الفوضى‪،‬حيــث‬\n      ‫تلقــت الدوريــات األمنيــة بــاغ مــن أحــد املواطنــن بتعرضــه إلطــاق نــار‬\n      ‫مــن شــقيقه املدعــى عليــه وباالنتقــال للموقــع مت القبــض عليــه واتضــح‬\n      ‫وجــود رائحــة تنبعــث مــن املدعــى عليــه وهــو بحالــة غيــر طبيعيــة‪،‬‬\n      ‫وأنكــر املدعــى عليــه الدعــوى ‪ ،‬وكانــت بينــة املدعــي العــام محضــر‬\n      ‫االستشــمام ومحضــر الدوريــات األمنيــة واملثبــت فيــه جتــرد املدعــى‬\n      ‫عليــه مــن مالبســه ماعــدا الســروال وأنــه يف حالــة غيــر طبيعيــة ومحضــر‬\n‫‪299‬‬\n\f‫تعــذر ســماع أقــوال املدعــى عليــه عنــد االســتجواب ألنــه يف حالــة غيــر‬\n‫طبيعية‪،‬وبتوجــه التهمــة القويــة لشــرب املدعــى عليــه املســكر بهــذه‬\n‫القرائــن ‪،‬فقــد حكمــت احملكمــة بتعزيــره باجللــد ســبعني جلــدة دفعــة‬\n‫واحــدة لعــدم ثبــوت إدانــة املدعــى عليــه مبــا جــاء يف الدعــوى ودرء حــد‬\n‫املســكر لعــدم ثبوتــه وصــرف النظــر عــن طلــب املدعــي العــام تعزيــر‬\n‫املدعــى عليــه لقــاء قيامــه بإحــداث الفوضــى وإثــارة املشــاكل مــع أخيــه‬\n‫لعــدم ثبوتــه ‪،‬وقنــع املدعــى عليــه ‪،‬واعتــرض املدعــي العــام بــدون الئحــة‬\n                             ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬    ‫ُ‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بنجــران برقــم ‪ 3444662‬وتاريــخ ‪1434/01/25‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34219112‬وتاريــخ ‪1434/01/25‬ه ـ ففــي يــوم‬\n‫األحد املوافق‪ 1434/02/17‬هـ افتتحت اجللســة الســاعة ‪ 09 : 00‬بشــأن‬\n‫دعــوى املدعــي ‪ .....‬واملكلــف مبهمــة اإلشــراف علــى مكتــب االدعــاء‬\n‫العــام مبحاكــم جنــران مبوجــب خطــاب رئيــس فــرع هيئــة التحقيــق‬\n‫واالدعــاء العــام مبنطقــة جنــران رقــم ‪.....‬وتاريــخ ‪1430/12/29‬ه ـ ضــد‬\n‫ا يف دعــواه‬ ‫‪.....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪.....‬قائ ـ ً‬\n‫عليــه إنــه ورد مبحضــر تنفيــذ املهمــة رقــم (‪).....‬وتاريــخ ‪1434/1/8‬ه ـ‬\n‫املعــد مــن قبــل الدوريــات األمنيــة بنجــران املتضمــن تلقيهــم بــاغ مــن‬\n‫املواطــن ‪.....‬بتعرضــه إلطــاق نــار عليــه داخــل املنــزل مــن قبــل شــقيقه‬\n‫املدعــى عليــه وباالنتقــال للموقــع املذكــور مت القبــض عليــه واتضــح‬\n\n                                                                                    ‫‪300‬‬\n\f      ‫عــدم وجــود أي طلــق نــاري أو ظــروف فارغــة باملوقــع واتضــح وجــود‬\n            ‫رائحــة تنبعــث مــن املدعــى عليــه كمــا أنــه بحالــة غيــر طبيعيــة ‪0‬‬\n      ‫وورد بإعــادة ضبــط أقــوال معــدي محضــر تنفيــذ املهمــة والــذي مضمونــه‬\n      ‫أنــه بتلقيهــم البــاغ انتقــل إلــى املوقــع ضابــط املربــع وانتظــر إلــى حــن‬\n      ‫وصــول الدعــم مــن قبــل رئيــس امليــدان ومت االنتقــال إلــى موقــع احلــادث‬\n      ‫وشــوهد املدعــى عليــه عنــد بــاب بيتــه مــن اخلــارج البس ـ ًا ســرواال‬\n      ‫أبيــض داخلــي فقــط ‪ -‬وهــو يف حالــة غيــر طبيعيــة وباســتدراجه مــن‬\n      ‫ال مــن (‪.....‬و‪.....‬مبنــع رجــال األمــن مــن‬ ‫قبلهــم والقبــض عليــه قــام ك ً‬\n      ‫أخــذ املدعــى عليــه ‪( -‬فــرزت لهــم أوراق بشــأن منعهــم لرجــال األمــن‬\n      ‫مــن أداء عملهــم وأحيلــت لهيئــة الرقابــة والتحقيــق باخلطــاب رقــم ‪.....‬‬\n      ‫وتاريــخ ‪1434/1/11‬ه ـ ) ومت الســيطرة عليهــم ونقلهــم للمركــز‬\n      ‫والعــودة إلــى املدعــى عليــه ونقلــه إلــى املركــز بواســطة أحــد أخوالــه‬\n      ‫بســيارته اخلاصــة وترافقــه الدوريــة األمنيــة وورد باحملضــر املعــد مــن‬\n      ‫قبــل ضابــط خفــر مركــز شــرطة ‪.....‬بتاريــخ ‪1434/1/9‬ه ـ تعذر ســماع‬\n      ‫أقــوال املدعــى عليــه لكونــه يف حالــة غيــر طبيعيــة وتنبعــث منــه رائحــة‬\n      ‫الســكر وباســتجواب املدعــي ‪..... /‬أفــاد بأنــه قــام باإلبــاغ عــن مضاربــة‬\n      ‫وأنــه ال يريــد مواصلــة دعــواه وباســتجواب املدعــى عليــه أفــاد بأنــه بينــه‬\n      ‫وبــن أخيــه املدعــي خالفــات ماليــة وعائليــة أفــرج عــن املدعــى عليــه‬\n      ‫اســتنادا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة وقــد ورد مبحضــر‬\n      ‫اإلستشــمام بتاريــخ ‪1434/1/9‬ه ـ املعــد مــن قبــل مركــز شــرطة ‪.....‬‬\n      ‫ومنــدوب هيئــة األمــر باملعــروف والنهــي عــن املنكــر اتضــح انبعــاث‬\n      ‫رائحــة مــن فيــه تشــبه رائحــة املســكر وقــد انتهــى التحقيــق إلــى توجيــه‬\n      ‫االتهــام ل ـ ‪..... /‬بشــرب املســكر وإحــداث الفوضــى بإثــارة املشــاكل مــع‬\n\n\n‫‪301‬‬\n\f                                         ‫أخيــه وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n         ‫‪ -1‬ما ورد مبحضر تنفيذ املهمة املنوه عنه واملرفق لفة رقم (‪. )5‬‬\n‫‪ -2‬مــا ورد مبحضــر إعــادة ضبــط معــدي محضــر تنفيــذ املهمــة املنــوه‬\n    ‫عنــه واملــدون ص (‪ )5-4‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪. )24‬‬\n‫‪ -3‬مــا جــاء يف محضــر اإلستشــمام املنــوه عنــه واملــدون ص (‪ )7‬مــن‬\n                  ‫دفتــر محاضــر التحقيــق اجلنائــي املرفــق لفــة رقــم (‪. )1‬‬\n‫‪ -4‬مــا جــاء يف أقــوال املتهــم املنــوه عنهــا واملدونــة ص (‪ )7-6‬مــن دفتــر‬\n                                                ‫التحقيــق املرفــق لفــة رقــم (‪. )24‬‬\n‫‪ -5‬مــا ورد مبحضــر تعــذر ســماع األقــوال املنــوه عنــه واملــدون ص (‪ )8‬مــن‬\n                       ‫دفتــر محاضــر التحقيــق اجلنائــي املرفــق لفــة رقــم (‪. )1‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه‪..... /‬وهــو بكامــل قــواه العقليــة‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n                                                       ‫إليــه واحلكــم عليــه باآلتــي‪:‬‬\n                                         ‫‪ -1‬عقوبة حد املسكر لقاء شربه له ‪.‬‬\n‫‪ -2‬عقوبــة تعزيريــة لقــاء إحــداث املشــاكل وإثــارة الفوضــى تردعــه‬\n                                                                      ‫وتزجــر غيــره ‪.‬‬\n‫وبــاهلل التوفيــق هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه‬\n‫قــال مــا ذكــره املدعــي العــام مــن قيامــي بشــرب املســكر فهــو غيــر‬\n‫ا ومــا ذكــره مــن قيامــي بإحــداث الفوضــى‬             ‫صحيــح جملــة وتفصي ـ ً‬\n‫بإثــارة املشــاكل مــع أخــي فهــو غيــر صحيــح والصحيــح هــو أنــي كنـ ُـت‬\n‫أطلــب حقــي مــن إرث والــدي الــذي اغتصبــه أخــي ولــم أقــم باالعتــداء‬\n‫عليــه مطلق ـ ًا هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي العــام هــل‬\n‫لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد لــدي بينــة ســوى مــا‬\n\n\n                                                                                          ‫‪302‬‬\n\f      ‫جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق واالطــاع علــى‬\n      ‫محضــر االستشــمام املــدون علــى ص ‪ 7‬مــن امللــف املرفــق علــى لفــة رقــم‬\n      ‫‪ 1‬وعلــى محضــر تعــذر ســماع األقــوال املــدون علــى ص ‪ 8‬مــن ذات امللــف‬\n      ‫كمــا جــرى منــي االطــاع علــى أقــوال معــدي محضــر الدوريــات األمنيــة‬\n      ‫ـاء علــى مــا‬\n                 ‫املدونــة علــى ص ‪ 5-4‬مــن امللــف املرفــق علــى لفــة رقــم ‪ 24‬فبنـ ً‬\n      ‫ســبق مــن الدعــوى واإلجابــة وحيــث إن املدعــى عليــه قــد أنكــر قيامــه‬\n      ‫بشــرب املســكر ولــم يعتــرف بذلــك حتقيقـ ًا وألن محضــر االستشــمام‬\n      ‫لــم يتضمــن ســوى شــهادة عضــو واحــد مــن أعضــاء هيئــة األمــر باملعــروف‬\n      ‫والنهــي عــن املنكــر ولتوجــه التهمــة القويــة علــى املدعــى عليــه بشــربه‬\n                                                 ‫املســكر املؤيــدة بالقرائــن اآلتيــة‪:‬‬\n      ‫‪ -1‬مــا جــاء يف محضــر االستشــمام املتضمــن بأنــه بعــد استشــمام رائحــة‬\n      ‫فــم املدعــى عليــه مــن قبــل عضــو هيئــة األمــر باملعــروف والنهــي عــن‬\n                                        ‫املنكــر تبــن انبعــاث رائحــة املســكر منــه‬\n      ‫‪ -2‬مــا جــاء يف محضــر تعــذر ســماع األقــوال املتضمــن بأنــه قــد تعــذر‬\n      ‫اســتجواب املدعــى عليــه ألنــه يف حالــة غيــر طبيعيــة وتنبعــث منــه رائحــة‬\n                                                                                ‫املســكر‬\n      ‫‪ -3‬مــا جــاء يف أقــوال معــدي محضــر الدوريــات األمنيــة املتضمــن بأنهمــا‬\n      ‫شــاهدا املدعــى عليــه متجــرد ًا مــن مالبســه وليــس عليــه إال ســروال‬\n      ‫أبيــض طويــل وهــو يف حالــة غيــر طبيعيــة ويهــذي وملــا كان مــن املقــرر‬\n      ‫فقهـ ًا أن التعزيــر ال يســقط بالشــبهة قــال جــال الديــن الســيوطي رحمــه‬\n      ‫اهلل‪ « :‬الشــبهة ال تســقط التعزيــر» ( األشــباه والنظائــر ‪ -‬ص ‪) 162‬‬\n      ‫ويقــول ابــن جنيــم رحمــه اهلل‪ « :‬التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا‬\n       ‫يثبــت مبــا يثبــت بــه املــال ويجــري فيــه احللــف ويقضــى فيــه بالنكــول»‬\n\n\n‫‪303‬‬\n\f‫( األشــباه والنظائــر ‪ -‬ص ‪ ) 157‬وحيــث إنــه لــم يثبــت قيــام املدعــى عليــه‬\n‫باالعتــداء علــى أخيــه وألن وجــود مشــكلة بــن املدعــى عليــه وبــن أخيــه‬\n‫ال يعــد مســوغ ًا لتعزيــره مــا لــم يثبــت كيديــة شــكواه عليــه وتأسيس ـ ًا‬\n‫علــى جميــع مــا ســبق فقــد قــررت مــا يأتــي أو ًال ‪ :‬لــم يثبــت لــدي إدانــة‬\n‫املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ثانيـ ًا ‪ :‬درء حــد املســكر‬\n‫عــن املدعــى عليــه لعــدم ثبــوت موجبــه ثالثـ ًا ‪ :‬تعزيــر املدعــى عليــه وذلــك‬\n‫بجلــده ســبعني جلــدة علن ـ ًا دفعــة واحــدة لقــاء توجــه التهمــة القويــة إليــه‬\n‫بتعاطــي املســكر رابع ـ ًا ‪ :‬صرفــت النظــر عــن مطالبــة املدعــي العــام‬\n‫بتعزيــر املدعــى عليــه لقــاء قيامــه بإحــداث الفوضــى بإثــارة املشــاكل‬\n‫مــع أخيــه لعــدم ثبــوت موجبــه هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليــه قنــع بــه كمــا قــرر املدعــي العــام اعتراضــه‬\n‫بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n             ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/17‬ه ـ الســاعة ‪09:30‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة بنجــران‬\n‫برقــم ‪ 34219112‬وتاريــخ ‪1434/3/8‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيل ــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 3443649‬وتاريــخ‬\n‫‪1434/2/23‬ه ـ اخلــاص بدعــوى املدعــي العــام ضـ ــد ‪..... /‬يف قضيــة (‬\n‫شــرب املســكر وإحــداث الفوضــى ) علــى الصفــة املوضحــة يف القــرار‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n               ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                        ‫‪304‬‬\n\f305\n\f306\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":299,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b1290b10301aa62afe9acc5d37e85451d3704df23f06f4aa28f9bdcd1f7ef464","normalized_text_hash":"6184cc60a0d803c38f5f7003817d55527e52988c2517ba2ac3ef628c87cd8a48","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p299-3443649"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
